INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('7acd795b-7a77-499d-a12f-1feff91d0357','ブロッコリーと卵のマヨネーズ和え','MAKE_AHEAD',NULL,'PT10M','PT30M',NULL,0,NULL,'[{"name":"ブロッコリー 2株"},{"name":"ゆで卵 5個"},{"name":"ツナ缶オイル漬け 2缶"},{"name":"白すりごま 大さじ2"},{"name":"マヨネーズ 大さじ2"},{"name":"しょうゆ 小さじ1"}]','[{"text":"ボウルに調味料とツナを合わせておく"},{"text":"ゆで卵を茹でる"},{"text":"ブロッコリー茹でる"},{"text":"ボールにゆで卵とブロッコリーを入れて混ぜる"}]','https://oceans-nadia.com/user/259228/recipe/434535',NULL,'{"name":"ブロッコリーと卵のマヨネーズ和え","recipeCategory":"","prepTime":"","cookTime":"","recipeIngredient":[],"recipeInstructions":[]}','',1773223134,1781751625);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('a9ff9ea4-a624-4036-a594-019c12a005b7','あんこ','MAKE_AHEAD',NULL,NULL,NULL,'{"name":"Infant"}',0,NULL,'[{"name":"小豆(さっと洗い 水気を切る) 250g"},{"name":"砂糖 90g"},{"name":"塩  二振り"},{"name":"水 800ml"}]','[{"text":"豆と水を入れる"},{"text":"圧力調理41分"},{"text":"砂糖と塩を入れて混ぜる。お玉で潰すとペースト状になる"}]','https://tfal.smart.link/o9vkdy16u?variant_id=243390&domain=PRO_COO','["a9ff9ea4-a624-4036-a594-019c12a005b7/158bfce2-7f90-4ed1-9a12-edc84b286c50-1000006101.png"]','{"name":"あんこ","recipeCategory":"","prepTime":"","cookTime":"","recipeIngredient":[],"recipeInstructions":[]}',replace('水700mlでは硬い\n\n41分である。砂糖は90g でオッケー\n水の量をなるべく正確に測った方がいいので重さを測る\n\n次は41分でやってみよう\n\n\n砂糖３割減で甘さ控えめに。\n砂糖と塩は最後に加える。\n一度わかしてお湯を捨てても良いかも\n\n必ず豆が柔らかくなったか確認する。\n硬いことがある。','\n',char(10)),1773280590,1784951637);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('bff6d072-3d61-4d7c-bbe3-f05239d96967','レンズ豆のサラダ','["MAKE_AHEAD"]',NULL,'PT10M','PT30M',NULL,0,NULL,'[{"name":"レンズ豆 300g"},{"name":"小さめ玉ねぎ2（大きめだったら1-1.5個）"},{"name":"にんじん1"},{"name":"水 700ccくらい。様子を見てちょっとずつ増やす"},{"name":"米油 60g"},{"name":"酢 30g"},{"name":"ディジョンマスタード．30g"},{"name":"塩 3g"}]','[{"text":"レンズ豆は洗ってザルにあげておく。玉ねぎと人参は粗いみじん切り。"},{"text":"厚手の鍋に、レンズ豆、人参、玉ねぎをいれ、ひたひたの水を注ぎ火にかけ、沸騰後、蓋をし弱火で30分。水は最終的に無くなっているのが望ましい。途中で様子を見つつ、増やす。"},{"text":"鍋に水が多く残っていたら捨てる。基本は捨てずにそのまま。鍋のなかに米油、マスタード、酢を混ぜ合わせ、塩コショウで味を整える。"}]','https://cookpad.com/jp/recipes/19847950','[]','{"name":"レンズ豆のサラダ","cookingMode":"MAKE_AHEAD","recipeCategory":"","tags":["豆","冷たい"],"prepTime":"PT10M","cookTime":"PT30M","url":"https://cookpad.com/jp/recipes/19847950","images":[],"recipeIngredient":[],"recipeInstructions":[]}',replace('ディジョンマスタードで作った方が美味しい。\n\n20260629 油を減らした\n\n\n2. 追加モジュールの提案（野菜のオプション）\n​食感や色彩のアップデートとして以下の候補を挙げました。\n​色彩（UI改善）: パセリ（緑）、赤パプリカ（赤）\n​食感（フィードバック強化）: セロリ、きゅうり\n​風味（深みの追加）: ミニトマト、にんにく、ローリエ、ベーコン\n​3. キーコンポーネント：赤ワインビネガー\n​特性: ブドウ由来の華やかな香りと力強い酸味、わずかな**渋み（タンニン）**が特徴。\n​コスト感: 日本の小売店では高価（500円〜1,000円超）だが、Amazon等で**高コスパな輸入品（MAILLE等）**が調達可能であることを確認。\n​代替案: 「米酢＋少々の赤ワイン」や「リンゴ酢」によるエミュレートも可能。\n​4. 本場フランス流（ル・ピュイ風）の仕様\n​より本格的なビルドを目指すなら：\n​香気成分: 煮込み時にブーケガルニ（ローリエ、タイム、パセリ、クローブを刺した玉ねぎ）を投入。\n​具材の最適化: 煮崩れしにくい小粒の緑レンズ豆を使用し、最後に生のエシャロットで香りを立たせる。\n​現状の「野菜と一緒に煮込む」手法は、豆に野菜の旨みを吸わせる非常に合理的なステップです。ここにAmazonで見つけた赤ワインビネガーと、仕上げのパセリを加えるだけで、一気に「ビストロ品質」へバージョンアップできそうですね。','\n',char(10)),1773445146,1785541986);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('34802711-0618-4c75-9b5f-f2f476f54a80','ミネストローネ','MAKE_AHEAD',NULL,'PT20M',NULL,NULL,0,NULL,'[{"name":"玉ねぎ 2"},{"name":"人参 1"},{"name":"セロリ 1"},{"name":"大根 1/2"},{"name":"豚肩ロース 300g（ベーコンがたくさんあるなら入れなくても良い）"},{"name":"ベーコン 三和の塊 1パック"},{"name":"トマトペースト2袋"},{"name":"鶏ガラ 7.5g"},{"name":"塩 7-8g"},{"name":"豆（レッドキドニー、大豆、ひよこ豆）200g"}]','[{"text":"豆は圧力調理で10分煮る"},{"text":"玉ねぎ人参セロリは細かい角切り、大根は大きめの角切りにする"},{"text":"肉と大根以外の野菜をじっくり炒める"},{"text":"大根とひたひたの水を入れて調味料全部入れる"},{"text":"30分から1時間煮る！。途中で豆を入れてもいい。"},{"text":"豆を入れて軽くかき混ぜて完成"}]',NULL,'[]','{"name":"ミネストローネ","cookingMode":"MAKE_AHEAD","recipeCategory":"","tags":[],"prepTime":"PT20M","cookTime":"","url":"","images":[],"recipeIngredient":[{"name":"玉ねぎ"},{"name":"人参セロリ"},{"name":"大根"},{"name":"豚肩ロース"},{"name":"ベーコン"},{"name":"トマトペースト2袋"},{"name":"鶏ガラ"},{"name":"塩"},{"name":"豆（レッドキドニー、大豆、ひよこ豆）"}],"recipeInstructions":[{"text":"肉と野菜を炒める\n"}]}',replace('入れたければいろんな野菜を入れてもオッケー。かぼちゃとかほうれん草とか1種類を大量に入れすぎなければ割と美味しい。\n野菜出汁を取ってもいい','\n',char(10)),1773446062,1784951636);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('ba0019f7-673f-401b-b8a4-3235a7b0a96f','チキンとキャベツの生姜ペッパースープ','["MAKE_AHEAD"]',NULL,'PT15M','PT30M',NULL,0,NULL,'[{"name":"生姜 1"},{"name":"鶏もも2枚"},{"name":"玉ねぎ 2個"},{"name":"人参 1本"},{"name":"セロリ 1本"},{"name":"キャベツ 1/2"},{"name":"塩 9g"},{"name":"ブラックペッパー 2.0g"},{"name":"クローブ 6"},{"name":"ローレル6"},{"name":"タイム 6"}]','[{"text":"キャベツ以外を炒める"},{"text":"水とスパイスハーブ及び塩鶏ガラを加える"},{"text":"沸騰したらキャベツを加えて10分から15分煮込む"}]',NULL,'["ba0019f7-673f-401b-b8a4-3235a7b0a96f/4b36535e-56b4-413b-931f-cf7ae12de36b-1000006052.jpg","ba0019f7-673f-401b-b8a4-3235a7b0a96f/73cefe36-be07-4fe0-a9f5-6bdd2d86fc00-1000006051.jpg"]','{"name":"チキンとキャベツの生姜ペッパースープ","cookingMode":"MAKE_AHEAD","recipeCategory":"","tags":[],"prepTime":"","cookTime":"","url":"","images":[],"recipeIngredient":[],"recipeInstructions":[]}','',1773463925,1783677259);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('a7da734e-ec53-4170-b8b1-eb809373cb3e','かぼちゃの煮物','MAKE_AHEAD',NULL,NULL,NULL,NULL,0,NULL,'[{"name":"かぼちゃ 1/2、だいたい1kgくらい"},{"name":"醤油 15g"},{"name":"砂糖 45g"},{"name":"塩 3g"}]','[{"text":"​かぼちゃは種とワタを除き、3～4cm角に切ります。皮の硬そうな部分があればそぎ落としておきます。"},{"text":"​重ならない大きさの鍋に、**かぼちゃの皮面を上（黄色い身の側を鍋底）**にして広げ入れます。"},{"text":"​水と砂糖を入れる。落としぶたをして中火で10分煮る"},{"text":"​醤油 大さじ1、塩 小さじ1/2を加えます\n​そのままさらに5〜7分ほど煮て完成"}]','https://www.google.com/amp/s/www.sirogohan.com/sp/recipe/kabocha/amp/','[]','{"name":"かぼちゃの煮物","cookingMode":"MAKE_AHEAD","recipeCategory":"","tags":[],"prepTime":"","cookTime":"","url":"https://www.google.com/amp/s/www.sirogohan.com/sp/recipe/kabocha/amp/","images":[],"recipeIngredient":[],"recipeInstructions":[]}',replace('かぼちゃ今後グラム表記で。\n','\n',char(10)),1773464628,1785541914);
