INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('9ee9d65d-1f15-4248-a55e-673a9921866f','卵焼き','DINNER',NULL,NULL,NULL,'{"name":"Infant"}',1,NULL,'[{"name":"卵4個"},{"name":"醤油3.0g"},{"name":"白砂糖13G"},{"name":"水100cc"},{"name":"片栗粉 小さじ1くらい"}]','[{"text":"先に醤油、砂糖、片栗粉、水を混ぜる"},{"text":"卵を入れて混ぜる"},{"text":"焼く"}]',NULL,'[]','{"name":"卵焼き","cookingMode":"MAKE_AHEAD","recipeCategory":"","tags":[],"prepTime":"","cookTime":"","suitableForKids":{"name":"Infant"},"url":"","images":[],"recipeIngredient":[{"name":"卵4個"},{"name":"醤油3.0g"},{"name":"白砂糖13G"},{"name":"水100cc"},{"name":"片栗粉 小さじ1くらい"}],"recipeInstructions":[{"text":"先に醤油、砂糖、片栗粉、水を混ぜる"},{"text":"卵を入れて混ぜる"},{"text":"焼く"}],"notes":""}',replace('弁当用に作るなら、少し水を減らしてもいいのでは？\n','\n',char(10)),1774169531,1776373888);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('2efe068e-ed22-4cf2-b32a-b1ec0ee24a63','ユビキタス（青菜の湯引き）','LUNCH',NULL,NULL,NULL,NULL,'pinned',NULL,'[{"name":"​レタス（外葉を中心に）：好きなだけ"},{"name":"​サラダ油：適量（だいたい30〜50gくらいが目安）"},{"name":"​オイスターソース：適量（湯引きしたレタスの重量の8%くらい）"}]','[{"text":"お湯を沸かし、表面がだいたい覆われるくらいの量のサラダ油を入れる。"},{"text":"​再沸騰したら、大まかにちぎったレタスを入れる。"},{"text":"​箸で沈め、すぐにザルに取る。"},{"text":"​皿に盛り、オイスターソースを全体にかける。"}]',NULL,'["2efe068e-ed22-4cf2-b32a-b1ec0ee24a63/747f2179-9351-4010-929f-a24122848d13-1000006121.jpg","2efe068e-ed22-4cf2-b32a-b1ec0ee24a63/2dd60a8f-71b3-4910-964b-83fac9d8a15f-1000006122.jpg"]','{"name":"ユビキタス","cookingMode":"MAKE_AHEAD","recipeCategory":"","tags":[],"prepTime":"","cookTime":"","url":"","images":[],"recipeIngredient":[],"recipeInstructions":[],"notes":""}',replace('​レタス以外でも、小松菜、チンゲン菜、豆苗、空芯菜、キャベツ、モロヘイヤなどなど、いろんな葉野菜でつくれます。要するに「青菜炒め」にしておいしい野菜なら、なんでもOK。個人的に特におすすめしたいのは、ほうれん草、そして菜の花です。レタスの外葉とほうれん草のミックスも、なかなかオツです。\n​野菜によってはゆで時間を少し長くすると良いですが、それでもせいぜい30秒でしょうか。ゆで野菜ではなく、「温めたサラダ」と捉えた方が良さそうです。\n​オイスターソースに、醤油、酢、ニンニク、ショウガなどを加えてオリジナルのタレをつくるのもいいと思います。でも僕は、いろいろ試した結果、「オイスターソースのみを最小限の量で」というのが、一番おいしいという結論に至りました。\n\n料理名は「湯引き」の単なる語呂合わせなんですけど、ユビキタスという言葉には、「至高の存在が遍在（いつでもどこにでも存在する）」という意味があり、この料理も、だいたいどんな葉もの野菜もこれでおいしくなる、という意味を重ね合わせています。哲学的！\nお湯の表面を油が覆った状態で野菜をさっとゆでることで、葉っぱの表面が、薄くまんべんなく油でコーティングされるのが、おいしさのポイント。余分な油は、葉を引き上げる時にお湯とともに流れ落ちていきます。\n味つけは、本当はなんだっていいんですが、オイスターソースは不思議と抜群によく合うんです。','\n',char(10)),1774301451,1774305798);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('09c41dd0-cae5-4e6c-b05a-6dd36d0cbfd0','概念ビーフシチュー','MAKE_AHEAD',NULL,'PT20M','PT30M',NULL,0,NULL,'[{"name":"豚肩ロース600g"},{"name":"玉ねぎ2個"},{"name":"人参1個"},{"name":"セロリ1本"},{"name":"トマトペースト4袋"},{"name":"塩 9g"},{"name":"鶏ガラ顆粒 2.5g"},{"name":"赤ワイン 450ml"},{"name":"ローリエ 6枚"},{"name":"タイム 6枝"},{"name":"クローブ 3粒"}]','[{"text":"フライパンで肉をこんがり焼く"},{"text":"同じフライパンで野菜を炒める"},{"text":"圧力鍋に炒めたやつと調味料とトマトペースト入れる"},{"text":"フライパンには赤ワインを入れてこびりついたやつとかを溶かし込んで圧力鍋に入れる"},{"text":"ヒタヒタになるまで水を入れる"},{"text":"圧力で15分煮込む"}]',NULL,'["09c41dd0-cae5-4e6c-b05a-6dd36d0cbfd0/cd95f41d-ae9f-4bb1-ae9d-ca33330799ae-1000006127.jpg","09c41dd0-cae5-4e6c-b05a-6dd36d0cbfd0/a6ce73ad-ae54-42fc-ab92-11e8e082b614-1000006128.jpg"]','{"name":"概念ビーフシチュー","cookingMode":"MAKE_AHEAD","recipeCategory":"","tags":[],"prepTime":"","cookTime":"","url":"","images":[],"recipeIngredient":[],"recipeInstructions":[],"notes":""}',replace('ミニマル 宴\n量はそこまでできない。\n豚肩ロースがない場合は、カレー用の豚肉とか、スペアリブもあり','\n',char(10)),1774305850,1781338897);
