INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('51f63771-b95d-4e23-a816-ae108c978172','卵焼き（ミニマル料理）','DINNER',NULL,NULL,NULL,NULL,'pinned',NULL,'[]','[]',NULL,'["51f63771-b95d-4e23-a816-ae108c978172/d79c0acf-429f-4522-98f6-c019c8d30d30-1000006129.jpg"]','{"name":"卵焼き（ミニマル料理）","cookingMode":"MAKE_AHEAD","recipeCategory":"","tags":[],"prepTime":"","cookTime":"","url":"","images":[],"recipeIngredient":[],"recipeInstructions":[],"notes":""}','',1774321553,1775251025);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('aa92621c-d978-4a7f-82d3-8df1d4269f10','おでん','MAKE_AHEAD',NULL,NULL,'PT1H15M',NULL,'pinned',NULL,'[{"name":"好みの具材"},{"name":"昆布とかつお節のだし汁 1.5L"},{"name":"砂糖 大さじ1"},{"name":"醤油（あれば薄口醤油）大さじ4（60ml）"},{"name":"みりん 大さじ4（60ml）"},{"name":"塩 小さじ1/3～1/2ほど"}]','[{"text":"おでんのだし汁は、いつもより少し多めのかつお節を使い、5～6分じっくりと煮出したものを使います。"},{"text":"鍋にだし汁1.5L、砂糖大さじ1、醤油とみりん各大さじ4、塩小さじ1/3～1/2を合わせます。"},{"text":"大きな鍋につゆの材料を合わせたら、大根、じゃが芋、厚揚げ、こんにゃく、玉子をはじめに入れます。沸いたら極弱火にして50分火にかけます。"},{"text":"50分たったら、練り物、里芋、ゆでた牛すじ肉などを入れて10分ほど煮てから火を止めます。必要であれば塩で味を調えます。"},{"text":"時間があるようなら、おでん鍋を火から外して一度冷めるまで待ち、その後再加熱してから食べるのがおすすめです。再加熱するときは、沸いてから極弱火で10～15分ほど火にかけ、熱々をいただきます。"}]','https://www.sirogohan.com/sp/recipe/oden/',NULL,'{"name":"おでん","cookingMode":"DINNER","cookTime":"PT1H15M","recipeIngredient":[{"name":"好みの具材"},{"name":"昆布とかつお節のだし汁 1.5L"},{"name":"砂糖 大さじ1"},{"name":"醤油（あれば薄口醤油）大さじ4（60ml）"},{"name":"みりん 大さじ4（60ml）"},{"name":"塩 小さじ1/3～1/2ほど"}],"recipeInstructions":[{"text":"おでんのだし汁は、いつもより少し多めのかつお節を使い、5～6分じっくりと煮出したものを使います。"},{"text":"鍋にだし汁1.5L、砂糖大さじ1、醤油とみりん各大さじ4、塩小さじ1/3～1/2を合わせます。"},{"text":"大きな鍋につゆの材料を合わせたら、大根、じゃが芋、厚揚げ、こんにゃく、玉子をはじめに入れます。沸いたら極弱火にして50分火にかけます。"},{"text":"50分たったら、練り物、里芋、ゆでた牛すじ肉などを入れて10分ほど煮てから火を止めます。必要であれば塩で味を調えます。"},{"text":"時間があるようなら、おでん鍋を火から外して一度冷めるまで待ち、その後再加熱してから食べるのがおすすめです。再加熱するときは、沸いてから極弱火で10～15分ほど火にかけ、熱々をいただきます。"}],"notes":""}','',1774585759,1774585811);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('5777a43e-bab0-4df7-b4e2-7722e4afbf88','かき玉スープ','LUNCH',NULL,'PT10M','PT15M','{"name":"Child"}',0,NULL,'[{"name":"卵 1個"},{"name":"長ねぎ 1/2本 (50g)"},{"name":"にんじん 1/3本 (50g)"},{"name":"水 600ml"},{"name":"鶏ガラスープ 4.5g"},{"name":"しょうゆ 7g"},{"name":"塩 ふたふり"},{"name":"片栗粉 小さじ2"},{"name":"水 大さじ3 (水溶き片栗粉用)"}]','[{"text":"長ねぎは薄い輪切りに、にんじんは3～4cm長さの細切りにする。卵は溶いておく。"},{"text":"鍋にだし汁を入れ火にかけ、煮立ったら長ねぎ、にんじん、しょうゆ大さじ1/2、塩ふたつまみを入れて10分ほど煮る。"},{"text":"沸騰しているところに溶き卵を流し入れ、軽くかき混ぜる。"},{"text":"卵に火が通ったら火を止めて再びかき混ぜ、水溶き片栗粉を入れ、再び弱火で加熱しとろみをつける。"},{"text":"子ども用は80mlほど×2食分を取り分け、水30mlずつ（分量外）を入れて薄める。"}]',NULL,'["uploads/96333cbc-631f-45a9-a6e6-5ed6915a5ddd-1000006145.jpg"]','{"name":"かき玉スープ","cookingMode":"DINNER","prepTime":"PT10M","cookTime":"PT15M","suitableForKids":{"name":"Child"},"images":["uploads/96333cbc-631f-45a9-a6e6-5ed6915a5ddd-1000006145.jpg"],"recipeIngredient":[{"name":"卵 1個"},{"name":"長ねぎ 1/2本 (50g)"},{"name":"にんじん 1/3本 (50g)"},{"name":"だし汁 600ml"},{"name":"しょうゆ 大さじ1/2"},{"name":"塩 ふたつまみ"},{"name":"片栗粉 小さじ2"},{"name":"水 大さじ3 (水溶き片栗粉用)"}],"recipeInstructions":[{"text":"長ねぎは薄い輪切りに、にんじんは3～4cm長さの細切りにする。卵は溶いておく。"},{"text":"鍋にだし汁を入れ火にかけ、煮立ったら長ねぎ、にんじん、しょうゆ大さじ1/2、塩ふたつまみを入れて10分ほど煮る。"},{"text":"沸騰しているところに溶き卵を流し入れ、軽くかき混ぜる。"},{"text":"卵に火が通ったら火を止めて再びかき混ぜ、水溶き片栗粉を入れ、再び弱火で加熱しとろみをつける。"},{"text":"子ども用は80mlほど×2食分を取り分け、水30mlずつ（分量外）を入れて薄める。"}],"notes":""}',replace('2026年5月23日ちょっと味濃くなるように修正。\n和風だしではなく、鶏ガラで作る','\n',char(10)),1774585944,1781950615);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('9210e969-b412-47c4-99aa-3a8cf798a27c','ひよこ豆のフムス','MAKE_AHEAD',NULL,'PT0M','PT30M',NULL,0,NULL,'[{"name":"ガルバンソー(ひよこ豆) 300g"},{"name":"ローレル(ホール) 2枚"},{"name":"塩 3g"},{"name":"ゴマ 60g"},{"name":"油 15g"},{"name":"レモン汁 60g"},{"name":"クミン 3g"}]','[{"text":"ひよこ豆は、さっと洗い鍋にたっぷりの水と一緒に1晩につけておく。"},{"text":"つけた水のまま、ローレルを加え、圧力調理で23分煮る。"},{"text":"ごまはすり鉢で擦る"},{"text":"ブレンダーで粉砕。お湯で緩めのポタージュくらいに"},{"text":"その他全てを加えて混ぜる。"},{"text":"800mlのタッパー2つに均等に入れる。それぞれ7割まで入るのが目安。入らなければお湯を足したほうがいいかも。"}]','https://tomiz.com/recipe/pro/detail/20210625145432',NULL,'{"name":"ひよこ豆のフムス","cookingMode":"MAKE_AHEAD","prepTime":"PT0M","cookTime":"PT30M","url":"https://tomiz.com/recipe/pro/detail/20210625145432","recipeIngredient":[{"name":"ガルバンソー(ひよこ豆) 200g"},{"name":"ニンニク・・・1片"},{"name":"オーガニック ローレル(ホール) 1枚"},{"name":"パセリの茎・・・適量"},{"name":"塩(シママース) 少々"},{"name":"茹で上がったガルバンソー(ひよこ豆)・・・約400g"},{"name":"ニンニク・・・少々"},{"name":"マコト 二度練りねりごま白 大さじ1"},{"name":"塩(シママース) 少々"},{"name":"バルベーラ ロレンツォNo.1 有機EVオリーブオイル 50cc"},{"name":"カエンペッパー(パウダー) 少々"},{"name":"ブラックペッパー(ホール) 少々"},{"name":"グルメミル 1個"},{"name":"プレーンなパン薄切り・・・適量"}],"recipeInstructions":[{"text":"ひよこ豆は、さっと洗い鍋にたっぷりの水と一緒に1晩につけておく。"},{"text":"つけた水のまま、ニンニク(皮をむいて)1片、ローレル、あればパセリの茎を入れて,アクを取りながら、柔らかくなるまで煮る。"},{"text":"指で潰れるくらい柔らかくなるまで煮る。(約1時間〜1時間半)"},{"text":"塩少々入れて、さらに10分ほど煮る。(水が足りなかったら足してひたひたにする) ゆで汁も使用するので取っておく。"},{"text":"フードプロセッサーに茹でたひよこ豆、茹で汁大匙1、白練りごまペーストを入れてミキサーにかける。"},{"text":"さらにエキストラバージンオリーブオイルを少しずつ加えながらペースト状にする。"},{"text":"様子を見て必要なら茹で汁を足して堅さを調節する。"},{"text":"すりおろしたニンニク少々、粗挽きコショウ、カエンペッパーで味を調えてさらにフードプロセッサーにかける"},{"text":"器に盛り付けて、さらにオリーブオイル、胡椒、カエンペッパー(分量外)をかける。味をみて必要なら塩をたす。"},{"text":"パンにつけていただく。"}],"notes":""}','次作るときは味噌と鶏ガラ顆粒を入れてみる',1774758031,1779962738);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('73c5cf63-941b-48ef-ab0a-65c9b8ecf431','白花豆の甘煮','MAKE_AHEAD',NULL,NULL,NULL,NULL,0,NULL,'[{"name":"白花豆250g "},{"name":"砂糖90g"},{"name":"塩2。振り"},{"name":"水 600ml"}]','[{"text":"白花豆は一晩つけておく。冷蔵庫だと全然戻らないので常温放置がいい"},{"text":"圧力鍋に全てを入れる。水は600ml"},{"text":"ティファールクックフォーミーで圧力調理23分"}]','https://tfal.smart.link/o9vkdy16u?variant_id=243501&domain=PRO_COO','[]','{"name":"白花豆の甘煮欲しいものがたくさんだね。あきら","cookingMode":"MAKE_AHEAD","recipeCategory":"","tags":[],"prepTime":"","cookTime":"","url":"","images":[],"recipeIngredient":[{"name":"白花豆250g "},{"name":"砂糖90g"},{"name":"塩2。振り"},{"name":"水たくさん"}],"recipeInstructions":[{"text":"白花豆は一晩つけておく"},{"text":"圧力鍋に全てを入れる"},{"text":"ティファールクックフォーミーで圧力調理23分"}],"notes":""}',replace('            金時豆の甘煮\n            \n            6 人分の材料\n\n金時豆(一晩水につける) 225g\n豆をつけた水 600ml\n砂糖 195g\n塩 小さじ3/4\n\n\nサマリー:\n\n	材料を準備する\n	すべての材料を入れ \n混ぜ合わせ、蒸しかごを上に\nのせる\n	圧力調理：23分\n	器に盛って\n \n','\n',char(10)),1775284128,1775641187);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('359d7664-66db-4d32-b5d3-2f85f3222011','さつまいもの黄金煮（あおい）','MAKE_AHEAD',NULL,'PT15M','PT10M','{"name":"Infant"}',0,NULL,'[{"name":"さつまいも 2-3本"},{"name":"水 蒸せる程度"},{"name":"砂糖 大さじ2"},{"name":"バター (食塩不使用) 10g"},{"name":"塩 少々"}]','[{"text":"さつまいもは皮をむき、1cm幅の半月切りかいちょう切りにする。水に5分ほどさらす。"},{"text":"鍋にAを煮立て、水気をきった1を入れ、落としぶたをして、ごく弱火で5分ほど煮る。"},{"text":"上下を返し、再び落としぶたをして弱火で5分ほど煮る。そのまま冷ます。"}]',NULL,'["uploads/b08fff17-8fa8-4b07-93d8-4cd652cccfe4-1000006177.jpg"]','{"name":"さつまいもの黄金煮（あおい）","cookingMode":"MAKE_AHEAD","prepTime":"PT15M","cookTime":"PT10M","suitableForKids":{"name":"Infant"},"recipeYield":{"value":2,"unit":"L"},"images":["uploads/b08fff17-8fa8-4b07-93d8-4cd652cccfe4-1000006177.jpg"],"recipeIngredient":[{"name":"さつまいも 2-3本"},{"name":"水 蒸せる程度"},{"name":"砂糖 大さじ2"},{"name":"バター (食塩不使用) 10g"},{"name":"塩 少々"}],"recipeInstructions":[{"text":"さつまいもは皮をむき、1cm幅の半月切りかいちょう切りにする。水に5分ほどさらす。"},{"text":"鍋にAを煮立て、水気をきった1を入れ、落としぶたをして、ごく弱火で5分ほど煮る。"},{"text":"上下を返し、再び落としぶたをして弱火で5分ほど煮る。そのまま冷ます。"}],"notes":"無水鍋で蓋をしてやるとよいかも"}','無水鍋で蓋をしてやるとよいかも',1775342213,1781338898);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('453651ba-5416-4217-9fe5-4578a98aeb7f','もやしのカレー炒め','LUNCH',NULL,NULL,'PT18M','{"name":"Infant"}',0,NULL,'[{"name":"もやし 1袋 (170g)"},{"name":"にんじん 1/4本 (50g)"},{"name":"ピーマン 2個 (30g)"},{"name":"ベーコン 3枚"},{"name":"油 大さじ1/2"},{"name":"しょうゆ 小さじ2/3"},{"name":"バーモント味付け、カレーパウダー 5振り"},{"name":"砂糖 3g？"}]','[{"text":"にんじん、ピーマンは4cm長さの細切りにする。もやしは2cm長さに切る。ベーコンは5mm幅の細切りにする。"},{"text":"フライパンに油をごく弱火で熱し、にんじん、ピーマンを7分ほど炒める。もやし、ベーコンを加え、弱火で10分ほど炒める。"},{"text":"A（しょうゆ、カレー粉、砂糖）を加え、さらに1分ほど炒める。"}]',NULL,'["uploads/c729fd1b-2b75-4b8c-be13-2f73f016ec03-1000006180.jpg"]','{"name":"もやしのカレー炒め","cookingMode":"MAKE_AHEAD","cookTime":"PT18M","suitableForKids":{"name":"Infant"},"images":["uploads/c729fd1b-2b75-4b8c-be13-2f73f016ec03-1000006180.jpg"],"recipeIngredient":[{"name":"もやし 2/3袋 (170g)"},{"name":"にんじん 1/4本 (50g)"},{"name":"ピーマン 1個 (30g)"},{"name":"ベーコン 2枚"},{"name":"油 大さじ1/2"},{"name":"しょうゆ 小さじ2/3"},{"name":"カレー粉 各少々"},{"name":"砂糖 各少々"}],"recipeInstructions":[{"text":"にんじん、ピーマンは4cm長さの細切りにする。もやしは2cm長さに切る。ベーコンは5mm幅の細切りにする。"},{"text":"フライパンに油をごく弱火で熱し、にんじん、ピーマンを7分ほど炒める。もやし、ベーコンを加え、弱火で10分ほど炒める。"},{"text":"A（しょうゆ、カレー粉、砂糖）を加え、さらに1分ほど炒める。"}],"notes":""}',replace('もやしはあまり動かさないことで歯ごたえを保つ\n\n2026年4月5日作ったけど、あきらは食べなかった。味は悪くないが、もうちょいスパイス感が欲しいかな','\n',char(10)),1775355891,1778293818);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('e14dd49c-47e9-4771-857d-825eaacca88a','しらす小松菜チャーハン','LUNCH',NULL,'PT10M','PT10M','{"name":"Children"}',0,NULL,'[{"name":"ごはん 700g（2合くらい）"},{"name":"しらす干し 50g"},{"name":"長ねぎ 半分"},{"name":"小松菜 2-3株"},{"name":"卵 2-3個"},{"name":"塩 3ふり"},{"name":"A 鶏がらスープの素 (顆粒) 5g"},{"name":"A しょうゆ 小さじ2"},{"name":"A ごま油 小さじ1"},{"name":"いりごま お好みでわしっと"}]','[{"text":"下準備：長ねぎと小松菜はみじん切りにする。"},{"text":"フライパンにごま油をひいて火にかけ、長ねぎ、小松菜、塩を入れて炒める。"},{"text":"①に溶き卵を入れ、ごはんを加えて炒め合わせる。"},{"text":"②にAを入れて混ぜ合わせる。"},{"text":"③にしらすとゴマを加えてさらに混ぜる"}]',NULL,'["uploads/f6cda737-c8ee-44d6-a423-0bcfecda0ea1-1000006182.jpg"]','{"name":"しらすチャーハン","cookingMode":"DINNER","prepTime":"PT10M","cookTime":"PT10M","suitableForKids":{"name":"Children"},"images":["uploads/f6cda737-c8ee-44d6-a423-0bcfecda0ea1-1000006182.jpg"],"recipeIngredient":[{"name":"ごはん 500g"},{"name":"しらす干し 50g"},{"name":"長ねぎ 3/10本 (30g)"},{"name":"小松菜 1/6束 (50g)"},{"name":"卵 1個"},{"name":"塩 ひとつまみ"},{"name":"A 鶏がらスープの素 (顆粒) 大さじ1/2"},{"name":"A しょうゆ 小さじ1"},{"name":"A ごま油 小さじ1"},{"name":"追加調味料 鶏がらスープの素 (顆粒) 小さじ1"},{"name":"追加調味料 しょうゆ 小さじ1"},{"name":"追加調味料 ごま油 小さじ1"}],"recipeInstructions":[{"text":"下準備：長ねぎと小松菜はみじん切りにする。"},{"text":"フライパンにごま油をひいて火にかけ、長ねぎ、小松菜、塩を入れて炒める。"},{"text":"①に溶き卵を入れ、ごはんを加えて炒め合わせる。"},{"text":"②にAを入れて混ぜ合わせる。"},{"text":"③にしらすを加えてさらに混ぜ、子ども用に110gほど×2食分をとりわける。"},{"text":"大人用2食分は、④の残りに追加調味料を入れて炒め合わせる（しょうゆとごま油は鍋肌からまわし入れる）。"}],"notes":""}','',1775358725,1780458421);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('908cde41-0401-4988-96da-1c065e28b96f','切り干し大根の煮物 うたまる','MAKE_AHEAD',NULL,'PT15M','PT20M','{"name":"Infant"}',0,NULL,'[{"name":"切り干し大根 (乾燥) 35g"},{"name":"にんじん 1/2本 (75g)"},{"name":"ちくわ 2本 (70g)"},{"name":"（オプション）油揚げ 1枚"},{"name":"ごま油 適量"},{"name":"【A】水 250ml"},{"name":"【A】酒 大さじ2"},{"name":"【A】みりん 大さじ1"},{"name":"【A】しょうゆ 小さじ2"},{"name":"【A】砂糖 小さじ1"}]','[{"text":"下準備：切り干し大根は水で戻し、水気をぎゅっとしぼって2cm長さに切る。にんじん、ちくわはそれぞれ2cm長さの細切りにする。"},{"text":"鍋にごま油をひいて火にかけ、切り干し大根、にんじん、ちくわを入れて1～2分炒める。"},{"text":"炒めた具材が入った鍋に【A】の調味料（水250ml、酒大さじ2、みりん大さじ1、しょうゆ小さじ2、砂糖小さじ1）を全て入れ、落としぶたをして弱めの中火で煮込む。煮汁が少なくなるまで煮詰める。"},{"text":"煮汁が少なくなったら、子ども用として30gほどを2食分とりわけ、器に盛る。"}]',NULL,'[]','{"name":"切り干し大根の煮物 うたまる","cookingMode":"MAKE_AHEAD","prepTime":"PT15M","cookTime":"PT20M","suitableForKids":{"name":"Infant"},"images":[],"recipeIngredient":[{"name":"切り干し大根 (乾燥) 35g"},{"name":"にんじん 1/2本 (75g)"},{"name":"ちくわ 2本 (70g)"},{"name":"（オプション）油揚げ 1枚"},{"name":"ごま油 適量"},{"name":"【A】水 250ml"},{"name":"【A】酒 大さじ2"},{"name":"【A】みりん 大さじ1"},{"name":"【A】しょうゆ 小さじ2"},{"name":"【A】砂糖 小さじ1"}],"recipeInstructions":[{"text":"下準備：切り干し大根は水で戻し、水気をぎゅっとしぼって2cm長さに切る。にんじん、ちくわはそれぞれ2cm長さの細切りにする。"},{"text":"鍋にごま油をひいて火にかけ、切り干し大根、にんじん、ちくわを入れて1～2分炒める。"},{"text":"炒めた具材が入った鍋に【A】の調味料（水250ml、酒大さじ2、みりん大さじ1、しょうゆ小さじ2、砂糖小さじ1）を全て入れ、落としぶたをして弱めの中火で煮込む。煮汁が少なくなるまで煮詰める。"},{"text":"煮汁が少なくなったら、子ども用として30gほどを2食分とりわけ、器に盛る。"}],"notes":""}',NULL,1775370935,1782726273);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('a8571471-e88c-4c64-8f25-6b4da5baf309','ポテトサラダ あおい','["MAKE_AHEAD"]',NULL,'PT15M','PT20M','{"name":"Children"}',0,NULL,'[{"name":"じゃがいも (メークイン) 4個 "},{"name":"きゅうり 1本"},{"name":"塩もみ用の塩 2g"},{"name":"ハム2袋"},{"name":"A 酢 小さじ2強"},{"name":"A 砂糖 少々"},{"name":"B マヨネーズ 50g"},{"name":"B 塩、こしょう 各少々"}]','[{"text":"じゃがいもは1cm幅のいちょう切りにして、水に5分ほどさらす。水から沸騰後10分ほど、フォークがすっとささるようになるまでゆでる。大きめのボウルに移して粗くつぶし、熱いうちに酢と砂糖を加えて混ぜ、粗熱を取る。"},{"text":"きゅうりはスライサーで輪切りして塩ひとつまみで塩もみ。ハムは細切り。"},{"text":"2の水けをしぼって1のボウルに加え、マヨネーズと胡椒を加えて和える。冷蔵庫で冷やす。"}]',NULL,'["uploads/fadc59d2-5ed5-4a10-be1e-4654e406e862-1000006186.jpg"]','{"name":"ポテトサラダ","cookingMode":"MAKE_AHEAD","prepTime":"PT15M","cookTime":"PT20M","suitableForKids":{"name":"Children"},"images":["uploads/fadc59d2-5ed5-4a10-be1e-4654e406e862-1000006186.jpg"],"recipeIngredient":[{"name":"じゃがいも (メークイン) 小2個 (200g)"},{"name":"きゅうり 1/2本 (60g)"},{"name":"ハム 3枚"},{"name":"A 酢 小さじ1強"},{"name":"A 砂糖 少々"},{"name":"B マヨネーズ 大さじ2と1/2"},{"name":"B 塩、こしょう 各少々"}],"recipeInstructions":[{"text":"じゃがいもは1cm幅のいちょう切りにして、水に5分ほどさらす。水から沸騰後10分ほど、フォークがすっとささるようになるまでゆでる。大きめのボウルに移して粗くつぶし、熱いうちにAを加えて混ぜ、粗熱を取る。"},{"text":"きゅうりはスライサーで輪切りして塩ひとつまみで塩もみ。ハムは細切り。"},{"text":"2の水けをしぼって1のボウルに加え、Bを加えて和える。冷蔵庫で冷やす。"}],"notes":"にんじんなんか入れない"}',replace('2026年5月10日 じゃがいも500gだった。マヨネーズの量はちょうどいいか。もうちょっと減らしてもいいかもくらい\n\nにんじんなんか入れない\n2026年4月26日 マヨネーズの量を減らした\n次からじゃがいもの重量を測る','\n',char(10)),1775372008,1784951633);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('12f77476-ae6b-47e4-a51f-9c51e19e34e6','マンドゥ餃子','DINNER',NULL,NULL,NULL,NULL,0,NULL,'[{"name":"マンドゥ餃子6個"},{"name":"油小さじ1"}]','[{"text":"フライパンに油を敷いて餃子を並べる"},{"text":"水100cc を入れて蓋をして火力5で加熱し沸騰したら火力3。蓋をしたまま4分半放置"},{"text":"蓋を取る。水が多く、残っていたらキッチンペーパーで拭き取りつつ火力5くらいで水を飛ばす"},{"text":"火力4で焼いて焼き色がついたら出来上がり"}]',NULL,'["12f77476-ae6b-47e4-a51f-9c51e19e34e6/1a7c30fc-3aab-4da4-a3d2-26c5c6a0dbcb-1000006190.jpg"]','{"name":"マンドゥ餃子","cookingMode":"MAKE_AHEAD","recipeCategory":"","tags":[],"prepTime":"","cookTime":"","url":"","images":[],"recipeIngredient":[{"name":"マンドゥ餃子6個"}],"recipeInstructions":[{"text":"フライパンに軽く油を敷いて餃子を並べる"},{"text":"水100cc を入れて蓋をして火力5で加熱し沸騰したら火力3。蓋をしてから4分半放置"},{"text":"蓋を取り水が多く、残っていたらキッチンペーパーで拭き取りつつ火力5くらいで水を飛ばす"},{"text":"火力4で焼いて焼き色がついたら出来上がり"}],"notes":""}','',1775386000,1775818673);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('88e65e13-36e0-49b8-b035-939ec0e4d42c','ムリガタニースープ 稲田','["MAKE_AHEAD"]',NULL,'PT15M','PT30M',NULL,1,NULL,'[{"name":"鶏もも肉 (角切り) 600g "},{"name":"玉ねぎ2個"},{"name":"にんじん1本"},{"name":"セロリ1本"},{"name":"ムング豆 (皮なし) 300g <または赤レンズ豆>"},{"name":"トマト (角切り) 2個もしくはトマトペースト1袋"},{"name":"水 適量"},{"name":"バター 60g"},{"name":"塩 10g"},{"name":"鶏ガラ顆粒 7.5g"},{"name":"カレー粉 12g"},{"name":"ブラックペッパーパウダー 6g"},{"name":"クミンパウダー 6g"},{"name":"パクチー (みじん切り) お好みで適量"}]','[{"text":"鍋にバターを熱し、にんにく、鶏肉、ベース野菜MIXを炒める。"},{"text":"肉の色が変わり、玉ねぎが少し透明になってきたら残りの材料とパクチー以外のスパイスを全て加える。"},{"text":"沸騰したら蓋をして豆が柔らかくなるまで煮込む(B)。"},{"text":"仕上げに、お好みでパクチーを加える。"}]',NULL,'["uploads/08eab129-3b64-4cad-a035-3197c21abe52-1000006257.webp"]','{"name":"ムリガタニースープ 稲田","cookingMode":"DINNER","prepTime":"PT15M","cookTime":"PT30M","images":["uploads/08eab129-3b64-4cad-a035-3197c21abe52-1000006257.webp"],"recipeIngredient":[{"name":"鶏もも肉 (角切り) 600g "},{"name":"玉ねぎ2個"},{"name":"にんじん1本"},{"name":"セロリ1本"},{"name":"ムング豆 (皮なし) 300g <または赤レンズ豆>"},{"name":"トマト (角切り) 2個もしくはトマトペースト1袋"},{"name":"水 適量"},{"name":"バター 60g"},{"name":"塩 10g"},{"name":"カレー粉 12g"},{"name":"ブラックペッパーパウダー 6g"},{"name":"クミンパウダー 6g"},{"name":"パクチー (みじん切り) お好みで適量"}],"recipeInstructions":[{"text":"鍋にバターを熱し、にんにく、鶏肉、ベース野菜MIXを炒める。"},{"text":"肉の色が変わり、玉ねぎが少し透明になってきたら残りの材料とパクチー以外のスパイスを全て加える。"},{"text":"沸騰したら蓋をして豆が柔らかくなるまで煮込む(B)。"},{"text":"仕上げに、お好みでパクチーを加える。"}],"notes":""}','',1775868015,1784352399);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('c9d34a77-acd0-4822-acc1-3a8a5f0f3452','青菜の白いミネストローネ','MAKE_AHEAD',NULL,NULL,'PT30M',NULL,0,NULL,'[{"name":"パンチェッタ (1cm幅に切る) 300g (またはベーコン)"},{"name":"玉ねぎ2個"},{"name":"にんじん1本"},{"name":"セロリ1本"},{"name":"白インゲン豆 200g"},{"name":"小松菜 (2cm長さに切る)  2袋"},{"name":"水 "},{"name":"オリーブオイル 90g"},{"name":"塩 13g"},{"name":"粉チーズ お好みで適量"},{"name":"ブラックペッパーパウダー 2.0g"},{"name":"タイム "},{"name":"オレガノ "},{"name":"バジル "}]','[{"text":"鍋にオリーブオイルを熱し、にんにく、パンチェッタ、ベース野菜MIXを炒める。"},{"text":"玉ねぎが少し透明になったら、粉チーズ以外の残りの材料とバジル以外のスパイスを全て加える。"},{"text":"もち麦が完全に柔らかくなるまで20～30分煮込み、最後にバジルを加える。お好みで、粉チーズや“追いオリーブオイル (分量外)”をたっぷりかけてもよい。"}]',NULL,'["uploads/ee1f9ffc-1ffe-4001-8e68-2f45e8b1627f-1000006338.webp"]','{"name":"もち麦と青菜の白いミネストローネ","cookingMode":"MAKE_AHEAD","cookTime":"PT30M","images":["uploads/ee1f9ffc-1ffe-4001-8e68-2f45e8b1627f-1000006338.webp"],"recipeIngredient":[{"name":"パンチェッタ (1cm幅に切る) 50g (またはベーコン)"},{"name":"玉ねぎ2個"},{"name":"にんじん1本"},{"name":"セロリ1本"},{"name":"白インゲン豆"},{"name":"小松菜 (2cm長さに切る)  2袋"},{"name":"水 "},{"name":"オリーブオイル 90g"},{"name":"塩 13g"},{"name":"粉チーズ お好みで適量"},{"name":"ブラックペッパーパウダー お好みで適量"},{"name":"タイム "},{"name":"オレガノ "},{"name":"バジル "},{"name":"バジル 2枚"}],"recipeInstructions":[{"text":"鍋にオリーブオイルを熱し、にんにく、パンチェッタ、ベース野菜MIXを炒める。"},{"text":"玉ねぎが少し透明になったら、粉チーズ以外の残りの材料とバジル以外のスパイスを全て加える。もち麦が完全に柔らかくなるまで20～30分煮込み、最後にバジルを加える。お好みで、粉チーズや“追いオリーブオイル (分量外)”をたっぷりかけてもよい。"}],"notes":""}','',1776487329,1777951114);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('08f6a0f8-6f6a-4fd5-8f21-8caf005998f9','手羽元のカレークリーム煮','MAKE_AHEAD',NULL,NULL,'PT10M','{"name":"Children"}',0,NULL,'[{"name":"鶏の手羽元 8本"},{"name":"玉ねぎ 1/2個"},{"name":"にんじん 1/2本"},{"name":"パプリカ (赤) 1/4個"},{"name":"いんげん 4本"},{"name":"オリーブオイル 大さじ1"},{"name":"小麦粉 大さじ1"},{"name":"バター 10g"},{"name":"カレー粉 小さじ1/2"},{"name":"オイスターソース 小さじ1"},{"name":"洋風スープの素（顆粒） 小さじ1"},{"name":"牛乳 200cc"}]','[{"text":"鶏の手羽元は骨に沿って切り込みを入れ、塩こしょうをふる。"},{"text":"玉ねぎ、にんじん、パプリカ、いんげんは5mmの角切りにする。"},{"text":"フライパンにオリーブオイルを入れて中火で熱し、手羽元の表面に焦げ目がつくように転がしながら焼く。2の野菜を入れて、蓋をして約10分弱火で蒸す。"},{"text":"小麦粉、バター、カレー粉、オイスターソース、洋風スープの素（顆粒）を加えよく混ぜた後、牛乳を3回に分けて入れ、その都度よくかき混ぜる。ソースにとろみがついたらお皿に盛る。"}]',NULL,'["uploads/d6c83301-0402-4aaa-ad42-a21824ecbef2-1000006350.jpg"]','{"name":"手羽元のカレークリーム煮","cookingMode":"MAKE_AHEAD","cookTime":"PT10M","suitableForKids":{"name":"Children"},"images":["uploads/d6c83301-0402-4aaa-ad42-a21824ecbef2-1000006350.jpg"],"recipeIngredient":[{"name":"鶏の手羽元 8本"},{"name":"玉ねぎ 1/2個"},{"name":"にんじん 1/2本"},{"name":"パプリカ (赤) 1/4個"},{"name":"いんげん 4本"},{"name":"オリーブオイル 大さじ1"},{"name":"小麦粉 大さじ1"},{"name":"バター 10g"},{"name":"カレー粉 小さじ1/2"},{"name":"オイスターソース 小さじ1"},{"name":"洋風スープの素（顆粒） 小さじ1"},{"name":"牛乳 200cc"}],"recipeInstructions":[{"text":"鶏の手羽元は骨に沿って切り込みを入れ、塩こしょうをふる。"},{"text":"玉ねぎ、にんじん、パプリカ、いんげんは5mmの角切りにする。"},{"text":"フライパンにオリーブオイルを入れて中火で熱し、手羽元の表面に焦げ目がつくように転がしながら焼く。2の野菜を入れて、蓋をして約10分弱火で蒸す。"},{"text":"小麦粉、バター、カレー粉、オイスターソース、洋風スープの素（顆粒）を加えよく混ぜた後、牛乳を3回に分けて入れ、その都度よくかき混ぜる。ソースにとろみがついたらお皿に盛る。"}],"notes":""}','2026年4月26日アキラは食べなかった',1776633956,1777882084);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('50db0c78-399b-4b80-aaac-d11cbb7a11f8','冷凍フライドポテト','DINNER',NULL,NULL,NULL,NULL,0,NULL,'[{"name":"冷凍ポテト120g"},{"name":"油ちょっと"},{"name":"塩3フリ"}]','[{"text":"大きいフライパンに油を小さじ1くらい敷いて火力5"},{"text":"ポテトを入れて火力5で熱しつつ十分あったまったら火力4で1分焼いてひっくり返すを繰り返す。目安として7分くらい焼けばいいんじゃないかな"},{"text":"焼き色がついたらお皿にとってキッチンペーパーで油取る"},{"text":"塩を振って混ぜる"}]',NULL,'[]','{"name":"冷凍ポテト焼く","cookingMode":"MAKE_AHEAD","recipeCategory":"","tags":[],"prepTime":"","cookTime":"","url":"","images":[],"recipeIngredient":[],"recipeInstructions":[],"notes":""}','',1776764542,1782899412);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('5e338353-7b14-457c-88f5-e43b50ec9b57','なすの醤油煮 基本形','LUNCH',NULL,'PT15M','PT30M',NULL,0,NULL,'[{"name":"なす (乱切り) 300g"},{"name":"サラダ油 30g"},{"name":"濃口醤油 20g"},{"name":"水 150g"}]','[{"text":"キッチン スケールで空の鍋を計量しておく。"},{"text":"鍋に材料をすべて入れる。"},{"text":"蓋をして、中火にかける。"},{"text":"ナスがしんなりするまでぐつぐつ煮る。もしあれば落とし蓋をすると満遍なく味が染みる。なければ、ないでOK。"},{"text":"しんなりしたら蓋を取り、さらに煮る。"},{"text":"味が染みて、完全にやわらかくなった状態にする。"},{"text":"計量し、中身が300gになっていたら完成。300gより多ければさらに煮る。少ないのにやわらかくなっていなければ、水を足してさらに煮る。"}]',NULL,'["uploads/ce2cbfe3-389c-4545-95e4-8e5b0b28aeb8-49ba2b3b-082b-4958-9052-22e589128ef6-1_all_19633.jpg"]','{"name":"なすの醤油煮 基本形","cookingMode":"MAKE_AHEAD","prepTime":"PT15M","cookTime":"PT30M","images":["uploads/ce2cbfe3-389c-4545-95e4-8e5b0b28aeb8-49ba2b3b-082b-4958-9052-22e589128ef6-1_all_19633.jpg"],"recipeIngredient":[{"name":"なす (乱切り) 300g"},{"name":"サラダ油 30g"},{"name":"濃口醤油 20g"},{"name":"水 150g"}],"recipeInstructions":[{"text":"キッチン スケールで空の鍋を計量しておく。"},{"text":"鍋に材料をすべて入れる。"},{"text":"蓋をして、中火にかける。"},{"text":"ナスがしんなりするまでぐつぐつ煮る。もしあれば落とし蓋をすると満遍なく味が染みる。なければ、ないでOK。"},{"text":"しんなりしたら蓋を取り、さらに煮る。"},{"text":"味が染みて、完全にやわらかくなった状態にする。"},{"text":"計量し、中身が300gになっていたら完成。300gより多ければさらに煮る。少ないのにやわらかくなっていなければ、水を足してさらに煮る。"}],"notes":""}','',1776911045,1777103356);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('e57fbfdf-0d08-4599-b91e-045252e96936','焼きそば（あおい）','LUNCH',NULL,'PT15M','PT25M','{"name":"Infant"}',0,NULL,'[{"name":"焼きそば用蒸し麺 3袋"},{"name":"にんじん 1/3本 (60g)"},{"name":"キャベツ 4枚 (190g)"},{"name":"もやし 1 袋"},{"name":"豚バラ薄切り肉 60g"},{"name":"油 大さじ1"},{"name":"焼きそば添付の粉ソース 2袋"},{"name":"青のり 少々"}]','[{"text":"にんじんは4cm長さの細切り、キャベツは3cm長さ、1cm幅の短冊切りにする。にら、もやしは2cm長さに切る。豚肉は1〜2cm幅に切る。"},{"text":"フライパンでキャベツ人参を炒める。割と火が通ったら豚肉を入れる"},{"text":"もやしと麺を同時に加え、水100ccを加えて麺をほぐす。もやしには自然と火がはいる。麺がほぐれたらソースを入れる。青のりを2つ掴みくらい入れる"}]',NULL,'["uploads/bd74e316-7f6b-4cfa-b82e-1b6fa02caaf0-1000006382.jpg"]','{"name":"焼きそば（あおい）","cookingMode":"MAKE_AHEAD","prepTime":"PT15M","cookTime":"PT25M","suitableForKids":{"name":"Infant"},"images":["uploads/bd74e316-7f6b-4cfa-b82e-1b6fa02caaf0-1000006382.jpg"],"recipeIngredient":[{"name":"焼きそば用蒸し麺 3袋"},{"name":"にんじん 1/3本 (60g)"},{"name":"キャベツ 4枚 (190g)"},{"name":"もやし 1 袋"},{"name":"豚バラ薄切り肉 60g"},{"name":"油 大さじ1"},{"name":"焼きそば添付の粉ソース 2袋"},{"name":"青のり 少々"}],"recipeInstructions":[{"text":"にんじんは4cm長さの細切り、キャベツは3cm長さ、1cm幅の短冊切りにする。にら、もやしは2cm長さに切る。豚肉は1〜2cm幅に切る。"},{"text":"焼きそば麺は袋の上から十字に包丁を入れて切る。ざるに入れ、水洗いしてやさしくほぐす。"},{"text":"フライパンに油を中火で熱し、にんじん、キャベツを5分ほど炒め、弱火でさらに5分ほど炒める。豚肉を加えて中火にし、色が変わるまで炒める。"},{"text":"にら、もやしを加えて8分ほど炒める。麺を加え、A（中濃ソース 大さじ4、塩 小さじ1/3）を加えて水分を飛ばすように3分ほど炒める。器に盛り、青のりをふる。"}],"notes":""}',replace('もとはあおいのやつだけど、相当変わってる\n','\n',char(10)),1777084617,1780189701);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('5135751b-65a1-4128-9439-21e1d5443019','茹でスナップエンドウ','LUNCH',NULL,'PT5M','PT2M30S','{"name":"Infant"}',0,NULL,'[{"name":"スナップエンドウ 150g"},{"name":"塩 少々"}]','[{"text":"スナップエンドウは両端のヘタと筋を取ります。"},{"text":"鍋にたっぷりの湯を沸かし、塩少々（分量外）を加えます。"},{"text":"沸騰したお湯にスナップエンドウを入れ、2分から2分半ほど茹でます。"},{"text":"茹で上がったらザルにあげて水気を切り、器に盛り付けます。"}]',NULL,NULL,'{"name":"茹でスナップエンドウ","cookingMode":"LUNCH","prepTime":"PT5M","cookTime":"PT2M30S","suitableForKids":{"name":"Infant"},"recipeIngredient":[{"name":"スナップエンドウ 150g"},{"name":"塩 少々"}],"recipeInstructions":[{"text":"スナップエンドウは両端のヘタと筋を取ります。"},{"text":"鍋にたっぷりの湯を沸かし、塩少々（分量外）を加えます。"},{"text":"沸騰したお湯にスナップエンドウを入れ、2分から2分半ほど茹でます。"},{"text":"茹で上がったらザルにあげて水気を切り、器に盛り付けます。"}],"notes":""}',NULL,1777084765,1777084765);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('1c6b2481-b793-44dc-93aa-da273392376e','チョコチップスコーン','LUNCH',NULL,'PT15M','PT10M','{"name":"Infant"}',0,NULL,'[{"name":"ホットケーキミックス 200g"},{"name":"菜種油 大さじ3"},{"name":"卵 1個"},{"name":"板チョコレート 20g"}]','[{"text":"ボウルにホットケーキミックスを入れ、菜種油を少しずつ加えてざっくりと混ぜます。"},{"text":"1のボウルに溶いた卵を数回に分けて入れ、粉っぽさがなくなるまで混ぜます。生地の硬さは耳たぶを目安に卵で調整してください。"},{"text":"刻んだチョコレートをざっくりと混ぜ込んだら、一口大に手でまとめます。トースターで熱が通りやすいよう、一口サイズにするのがおすすめです。"},{"text":"オーブントースターで約10分焼きます。ふんわりと膨らんだらできあがりです。"}]',NULL,'["uploads/778d4f07-3f04-4a90-ab74-aab394835b1c-1000006383.jpg","1c6b2481-b793-44dc-93aa-da273392376e/4ce49455-db24-42e9-9c8d-2b660d3db4c3-1000006710.jpg"]','{"name":"チョコチップスコーン","cookingMode":"MAKE_AHEAD","prepTime":"PT15M","cookTime":"PT10M","suitableForKids":{"name":"Infant"},"images":["uploads/778d4f07-3f04-4a90-ab74-aab394835b1c-1000006383.jpg"],"recipeIngredient":[{"name":"ホットケーキミックス 200g"},{"name":"菜種油 大さじ3"},{"name":"卵 1個"},{"name":"板チョコレート 20g"}],"recipeInstructions":[{"text":"ボウルにホットケーキミックスを入れ、菜種油を少しずつ加えてざっくりと混ぜます。"},{"text":"1のボウルに溶いた卵を数回に分けて入れ、粉っぽさがなくなるまで混ぜます。生地の硬さは耳たぶを目安に卵で調整してください。"},{"text":"刻んだチョコレートをざっくりと混ぜ込んだら、一口大に手でまとめます。トースターで熱が通りやすいよう、一口サイズにするのがおすすめです。"},{"text":"オーブントースターで約10分焼きます。ふんわりと膨らんだらできあがりです。"}],"notes":""}',replace('美味しい。\n簡単にできるのがいい。\nしかし、スーパージャンクフードである、、、','\n',char(10)),1777103511,1781338964);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('3e377e53-0e39-4286-8cf6-2bb98b058a77','にんじんしりしり（ゆうたろう実家版）','["MAKE_AHEAD"]',NULL,'PT5M','PT10M','{"name":"Kids"}',0,NULL,'[{"name":"人参 2本"},{"name":"ツナ缶（オイル漬けのもの） １缶"},{"name":"卵 2個"},{"name":"牛乳 20g"},{"name":"醤油 10g"},{"name":"だしの素 2.5g"}]','[{"text":"人参を千切りにします。スライサーやしりしり器があると便利です。"},{"text":"ツナ缶のフタを開ける前に缶を軽く水ですすぎます。フタで中身をぎゅっと抑え、フライパンに油を絞り入れます。"},{"text":"油が温まったら人参を入れ、じっくり炒めます。"},{"text":"人参がしんなりしてきたらツナを加えます。だしの素と醤油を入れ、味付けします。"},{"text":"卵に牛乳を入れて溶き、全体に回しながら流し入れます。人参に絡ませながら炒め、最後に塩胡椒で味を整えます。"},{"text":"完成です。"},{"text":"小分けして冷凍しておけば、朝お弁当にポンと入れるだけで楽ちんです。"}]','https://cookpad.com/jp/recipes/18657729','["3e377e53-0e39-4286-8cf6-2bb98b058a77/255d9c17-353c-4af1-b32b-7898dfdcb88d-1000007396.png"]','{"name":"人参しりしり（ゆうたろう実家版）","cookingMode":"MAKE_AHEAD","prepTime":"PT5M","cookTime":"PT10M","suitableForKids":{"name":"Kids"},"url":"https://cookpad.com/jp/recipes/18657729","recipeIngredient":[{"name":"人参 大１本"},{"name":"ツナ缶（オイル漬けのもの） １缶"},{"name":"卵 １個"},{"name":"牛乳 小さじ２"},{"name":"醤油 小さじ２"},{"name":"だしの素 小さじ１"},{"name":"塩胡椒(お好みで) 適量"}],"recipeInstructions":[{"text":"人参を千切りにします。スライサーやしりしり器があると便利です。"},{"text":"ツナ缶のフタを開ける前に缶を軽く水ですすぎます。フタで中身をぎゅっと抑え、フライパンに油を絞り入れます。"},{"text":"油が温まったら人参を入れ、じっくり炒めます。"},{"text":"人参がしんなりしてきたらツナを加えます。だしの素と醤油を入れ、味付けします。"},{"text":"卵に牛乳を入れて溶き、全体に回しながら流し入れます。人参に絡ませながら炒め、最後に塩胡椒で味を整えます。"},{"text":"完成です。"},{"text":"小分けして冷凍しておけば、朝お弁当にポンと入れるだけで楽ちんです。"}],"notes":""}','味を薄めに調整済み',1777630986,1784336929);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('678859d1-3d8e-4203-930a-732fbe066b58','焼きうどん（うたまる）','LUNCH',NULL,'PT10M','PT15M','{"name":"Infant"}',0,NULL,'[{"name":"うどん 3玉 (600g)"},{"name":"豚バラ肉 100g"},{"name":"にんじん 1/2本 (50g)"},{"name":"キャベツ 1/2個"},{"name":"酒 大さじ2"},{"name":"砂糖 小さじ1"},{"name":"あじの素 5振り"},{"name":"塩 ひとつまみ"},{"name":"ごま油 適量"},{"name":"かつお節 適宜"},{"name":"しょうゆ 小さじ2"},{"name":"塩 ふたつまみ"}]','[{"text":"豚肉は2~3cm幅に、にんじんは0.5cm幅のいちょう切りに、キャベツは2~3cm角に切る。"},{"text":"冷凍うどんは電子レンジで袋の表示時間通りに加熱し、解凍する。"},{"text":"フライパンにごま油をひいて火にかけ、豚肉を入れ肉の色が変わるまで炒める。"},{"text":"にんじんとキャベツを加えてしんなりするまで炒める。"},{"text":"うどんを加える。うどんが柔らかくなるように、水を150cc は加える。うどんが柔らかくなるよう様子を見る"},{"text":"酒大さじ2、砂糖小さじ1、あじの素5振りを加えて、味が全体になじむように炒める。"},{"text":"かつお節をふる。"}]',NULL,'["uploads/bda140a6-a5c7-4bed-a5fc-67763ccf115a-1000006525.jpg"]','{"name":"焼きうどん（うたまる）","cookingMode":"DINNER","prepTime":"PT10M","cookTime":"PT15M","suitableForKids":{"name":"Infant"},"images":["uploads/bda140a6-a5c7-4bed-a5fc-67763ccf115a-1000006525.jpg"],"recipeIngredient":[{"name":"冷凍うどん 3玉 (600g)"},{"name":"豚バラ肉 100g"},{"name":"にんじん 1/3本 (50g)"},{"name":"キャベツ 2枚 (100g)"},{"name":"酒 大さじ2"},{"name":"砂糖 小さじ1"},{"name":"あじの素 5振り"},{"name":"塩 ひとつまみ"},{"name":"ごま油 適量"},{"name":"かつお節 適宜"},{"name":"しょうゆ 小さじ2"},{"name":"塩 ふたつまみ"}],"recipeInstructions":[{"text":"豚肉は2~3cm幅に、にんじんは0.5cm幅のいちょう切りに、キャベツは2~3cm角に切る。"},{"text":"冷凍うどんは電子レンジで袋の表示時間通りに加熱し、解凍する。"},{"text":"フライパンにごま油をひいて火にかけ、豚肉を入れ肉の色が変わるまで炒める。"},{"text":"にんじんとキャベツを加えてしんなりするまで炒める。"},{"text":"うどんと酒大さじ2、砂糖小さじ1、あじの素5振りを加えて、味が全体になじむように炒める。"},{"text":"大人用、子ども用の両方にお好みでかつお節をふる。"}],"notes":"野菜は増量しよう"}',replace('多分雰囲気でもやし加えてもオッケー\nうどんは柔らかくなるように水をたくさん入れるか、もう先に茹でとくといいかも\n','\n',char(10)),1777882315,1778288416);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('516fe313-1604-4a6b-abcf-4d5b0100ab20','ほっこり味のサムゲタン','MAKE_AHEAD',NULL,'PT10M','PT50M','{"name":"Infant"}',0,NULL,'[{"name":"鶏の手羽元 8本"},{"name":"椎茸 6枚"},{"name":"長ねぎ 2本"},{"name":"生姜 1/2かけ"},{"name":"にんにく 2かけ"},{"name":"ごぼう 1/2本"},{"name":"大根 1/3本"},{"name":"自然塩 適量"},{"name":"米 大さじ2"},{"name":"水 400cc"},{"name":"ごま油 大さじ1"},{"name":"塩麹 大さじ2"}]','[{"text":"大根は乱切り、長ねぎとごぼうは3mmの斜め切り、椎茸と生姜は2mmにスライスする。にんにくは皮をむいて薄切りにする。手羽元には塩（分量外ひとつまみ）をふり、約10分おいて水気を拭く。"},{"text":"鍋底に塩をふり、手羽元、椎茸、長ねぎ、生姜、にんにく、ごぼう、大根を層にして入れ、上からひとつまみ塩をふる。"},{"text":"蓋をして弱火で約20分蒸し、鍋の間から蒸気がたって野菜から水分が出てきたら全体をかき混ぜる。米と水を入れて再度蓋をして約30分弱火で煮込む。"},{"text":"米が崩れて全体にとろみが出てきたら、ごま油を回し入れ、塩麹で味を整える。"}]',NULL,'["uploads/d703d06e-23c4-45f5-a8f9-3a7282f27239-1000006548.jpg"]','{"name":"ほっこり味のサムゲタン","cookingMode":"MAKE_AHEAD","tags":["ごはんさん"],"prepTime":"PT10M","cookTime":"PT50M","suitableForKids":{"name":"Infant"},"recipeYield":{"value":2,"unit":"L"},"images":["uploads/d703d06e-23c4-45f5-a8f9-3a7282f27239-1000006548.jpg"],"recipeIngredient":[{"name":"鶏の手羽元 8本"},{"name":"椎茸 6枚"},{"name":"長ねぎ 2本"},{"name":"生姜 1/2かけ"},{"name":"にんにく 2かけ"},{"name":"ごぼう 1/2本"},{"name":"大根 1/3本"},{"name":"自然塩 適量"},{"name":"米 大さじ2"},{"name":"水 400cc"},{"name":"ごま油 大さじ1"},{"name":"塩麹 大さじ2"}],"recipeInstructions":[{"text":"大根は乱切り、長ねぎとごぼうは3mmの斜め切り、椎茸と生姜は2mmにスライスする。にんにくは皮をむいて薄切りにする。手羽元には塩（分量外ひとつまみ）をふり、約10分おいて水気を拭く。"},{"text":"鍋底に塩をふり、手羽元、椎茸、長ねぎ、生姜、にんにく、ごぼう、大根を層にして入れ、上からひとつまみ塩をふる。"},{"text":"蓋をして弱火で約20分蒸し、鍋の間から蒸気がたって野菜から水分が出てきたら全体をかき混ぜる。米と水を入れて再度蓋をして約30分弱火で煮込む。"},{"text":"米が崩れて全体にとろみが出てきたら、ごま油を回し入れ、塩麹で味を整える。"}],"notes":""}',replace('1.5倍料で作るとだいたい3 L ぐらいになる\n水分多めの意識で作る。','\n',char(10)),1777942266,1778235263);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('a9417b2b-b71d-491d-9195-7925ea614b11','蓮根と厚切りベーコンのバターソテー','DINNER',NULL,'PT10M','PT10M','{"name":"Kids"}',0,NULL,'[{"name":"蓮根 300g"},{"name":"厚切りベーコン 50g"},{"name":"油 適量"},{"name":"バター 10g"},{"name":"醤油 小さじ1"},{"name":"塩 適量"}]','[{"text":"蓮根は半分に切り、皮付きのまま2mmの薄切りにする。ベーコンは1cm幅に切る。"},{"text":"フライパンに油を熱し、ベーコンがこんがりするまで弱火で炒める。"},{"text":"蓮根を加えて中火で炒め、全体に火が通ったらバターと醤油を入れ、塩で味を整える。"}]',NULL,'["uploads/537c8411-d7fc-497e-ab44-e17b0b9e142d-1000006546.jpg","a9417b2b-b71d-491d-9195-7925ea614b11/5a4d95fe-0184-48a6-8414-f04f39880292-1000006660.png"]','{"name":"蓮根と厚切りベーコンのバターソテー","cookingMode":"DINNER","tags":["ごはんさん"],"prepTime":"PT10M","cookTime":"PT10M","suitableForKids":{"name":"Kids"},"recipeYield":{"value":3,"unit":"食分"},"images":["uploads/537c8411-d7fc-497e-ab44-e17b0b9e142d-1000006546.jpg"],"recipeIngredient":[{"name":"蓮根 300g"},{"name":"厚切りベーコン 50g"},{"name":"油 適量"},{"name":"バター 10g"},{"name":"醤油 小さじ1"},{"name":"塩 適量"}],"recipeInstructions":[{"text":"蓮根は半分に切り、皮付きのまま2mmの薄切りにする。ベーコンは1cm幅に切る。"},{"text":"フライパンに油を熱し、ベーコンがこんがりするまで弱火で炒める。"},{"text":"蓮根を加えて中火で炒め、全体に火が通ったらバターと醤油を入れ、塩で味を整える。"}],"notes":""}','三和の肉のパックに入ってる塊ベーコンを使った',1777942941,1778914939);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('34c10496-aa2f-4cd6-bcc7-341614ccdfb7','ふわふわチキンナゲット','DINNER',NULL,'PT45M','PT5M','{"name":"Children"}',0,NULL,'[{"name":"鶏挽肉 200g"},{"name":"玉ねぎ 1/4個"},{"name":"小松菜 1株"},{"name":"にんじん 1/3本"},{"name":"木綿豆腐 1/2丁"},{"name":"片栗粉 大さじ1"},{"name":"醤油 小さじ1"},{"name":"揚げ油 適量"}]','[{"text":"豆腐はペーパータオルに包み、上からお皿などで重石をして約30分、水切りします。玉ねぎ、小松菜はみじん切りに、にんじんはすりおろします。"},{"text":"ボウルにすべての材料を入れてよくこねます。"},{"text":"フライパンに油を高さ2cm入れ、中温に熱し、柔らかすぎても手で丸められないので、スプーンを使って一口大にしてからそっとタネを落とし入れます。時々返しながら、約5分揚げます。"}]',NULL,'["uploads/0e0ae90c-dfb1-4b84-9a5e-87c0a03b1fc3-1000006547.jpg"]','{"name":"ふわふわチキンナゲット","cookingMode":"DINNER","prepTime":"PT45M","cookTime":"PT5M","suitableForKids":{"name":"Children"},"recipeYield":{"value":3,"unit":"食分"},"images":["uploads/0e0ae90c-dfb1-4b84-9a5e-87c0a03b1fc3-1000006547.jpg"],"recipeIngredient":[{"name":"鶏挽肉 200g"},{"name":"玉ねぎ 1/4個"},{"name":"小松菜 1株"},{"name":"にんじん 1/3本"},{"name":"木綿豆腐 1/2丁"},{"name":"片栗粉 大さじ1"},{"name":"醤油 小さじ1"},{"name":"揚げ油 適量"}],"recipeInstructions":[{"text":"豆腐はペーパータオルに包み、上からお皿などで重石をして約30分、水切りします。玉ねぎ、小松菜はみじん切りに、にんじんはすりおろします。"},{"text":"ボウルにすべての材料を入れてよくこねます。"},{"text":"フライパンに油を高さ2cm入れ、中温に熱し、柔らかすぎても手で丸められないので、スプーンを使って一口大にしてからそっとタネを落とし入れます。時々返しながら、約5分揚げます。"}],"notes":""}',replace('うまい。薄味だけど食べ始めると止まらない。\n次は鶏ガラを入れてもよいかも。','\n',char(10)),1777943049,1778288449);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('fd133a7b-c69b-489a-9ada-277a73825c40','ナポリタン（うたまる）','LUNCH',NULL,'PT10M','PT15M','{"name":"Infant"}',0,NULL,'[{"name":"スパゲティ（乾燥，太めのやつ） 300g"},{"name":"玉ねぎ 1個"},{"name":"ピーマン 2個 "},{"name":"マッシュルーム 7-8個 "},{"name":"ウインナーソーセージ 1袋"},{"name":"コンソメ（顆粒） 小さじ 1/2"},{"name":"トマトケチャップ 大さじ 2"},{"name":"砂糖 小さじ 1"},{"name":"ウスターソース 小さじ 1"},{"name":"油 適量"}]','[{"text":"玉ねぎは薄切りを半分に切る。ピーマンはみじん切り、マッシュルームは薄切り、ウインナーは0.5cm幅の輪切りにする。"},{"text":"鍋に湯（分量外）を2L沸かし、塩10g入れ、スパゲティを袋の表示時間に1分30秒ほど足してゆでる。"},{"text":"（茹でている間に）フライパンにオリーブオイルをひいて火にかけ、玉ねぎ、ピーマン、ウインナーソーセージ、マッシュルームを炒める。"},{"text":"しんなりとして火が通ったらAを入れ、弱めの中火で1分ほど炒める。"},{"text":"スパゲティがゆで上がったらザルにあげて水気を切り、③に入れて弱めの中火でなじませる。"},{"text":"油感が薄かったら、バターとか足すとよい"}]',NULL,'["uploads/57fc1e15-2ec9-4405-b3d7-02e97ae8392b-1000006600.jpg"]','{"name":"ナポリタン（うたまる）","cookingMode":"LUNCH","suitableForKids":{"name":"Infant"},"recipeYield":{"value":3,"unit":"食分"},"images":["uploads/57fc1e15-2ec9-4405-b3d7-02e97ae8392b-1000006600.jpg"],"recipeIngredient":[{"name":"スパゲティ（乾燥，太めのやつ） 300g"},{"name":"玉ねぎ 1個"},{"name":"ピーマン 2個 "},{"name":"マッシュルーム 7-8個 "},{"name":"ウインナーソーセージ 1袋"},{"name":"コンソメ（顆粒） 小さじ 1/2"},{"name":"トマトケチャップ 大さじ 2"},{"name":"砂糖 小さじ 1"},{"name":"ウスターソース 小さじ 1"},{"name":"油 適量"}],"recipeInstructions":[{"text":"玉ねぎは薄切りを半分に切る。ピーマンはみじん切り、マッシュルームは薄切り、ウインナーは0.5cm幅の輪切りにする。"},{"text":"鍋に湯（分量外）を2L沸かし、塩10g入れ、スパゲティを袋の表示時間に1分30秒ほど足してゆでる。"},{"text":"（茹でている間に）フライパンにオリーブオイルをひいて火にかけ、玉ねぎ、ピーマン、ウインナーソーセージ、マッシュルームを炒める。"},{"text":"しんなりとして火が通ったらAを入れ、弱めの中火で1分ほど炒める。"},{"text":"スパゲティがゆで上がったらザルにあげて水気を切り、③に入れて弱めの中火でなじませる。"},{"text":"油感が薄かったら、バターとか足すとよい"}],"notes":"野菜を大幅に増量"}','野菜を大幅に増量',1778300869,1780200151);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('e8e54db2-1af7-40ac-88d2-04dee637fa37','ズッキーニの焼いたん','LUNCH',NULL,'PT5M','PT5M','{"name":"Infant"}',0,NULL,'[{"name":"ズッキーニ1本"},{"name":"塩ひとふり"}]','[{"text":"ズッキーニは半月切り"},{"text":"フライパンに油を敷いて火力5で焼く"},{"text":"両面に焼き色がつくまで焼く"},{"text":"最後に塩を一振りしてまぶす"}]',NULL,'["e8e54db2-1af7-40ac-88d2-04dee637fa37/95a7d92d-f84d-400e-8625-321c44de1c85-1000006601.jpg","e8e54db2-1af7-40ac-88d2-04dee637fa37/1769e5f3-845f-4513-b241-1d2b7821fd58-1000006599.jpg","e8e54db2-1af7-40ac-88d2-04dee637fa37/27a9a483-1072-4e09-aab2-5879ff1b8528-1000006592.png"]','{"name":"ズッキーニの焼いたん","cookingMode":"LUNCH","recipeCategory":"","tags":[],"prepTime":"PT5M","cookTime":"PT5M","suitableForKids":{"name":"Infant"},"url":"","images":[],"recipeIngredient":[{"name":"ズッキーニ1本"},{"name":"塩ひとふり"}],"recipeInstructions":[{"text":"ズッキーニは半月切り"},{"text":"フライパンに油を敷いて火力5で焼く"},{"text":"両面に焼き色がつくまで焼く"},{"text":"最後に塩を一振りしてまぶす"}],"notes":"2026年5月9日アキラ食べた"}','2026年5月9日アキラ食べた',1778301073,1780200149);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('867496a2-8944-433a-8e94-590a3379d441','言ったもん勝ちボルシチ','MAKE_AHEAD',NULL,'PT15M','PT30M',NULL,0,NULL,'[{"name":"牛かたまり肉（もしくは豚肩ロース） 300g"},{"name":"バター 20g"},{"name":"薄切り野菜（玉ネギ必須、にんじん、大根、セロリなど） 計600g"},{"name":"塩 10g（鶏ガラも使う）"},{"name":"黒コショウ 適量"},{"name":"水 300g"},{"name":"トマトペースト 3袋"},{"name":"ローリエ 3枚"},{"name":"キャベツ (大まかに切る) 300g"}]','[{"text":"鍋に牛かたまり肉、薄切りにしたニンニク、バター、薄切りにした野菜（玉ネギ、にんじん、大根、セロリなど）、塩、黒コショウを全て入れ、中火にかける。"},{"text":"肉の表面の色が変わり、野菜がしんなりするまで炒める。（ヒント：もし面倒であればこの炒める工程は省略しても良いが、炒めるとコクが出ます。）"},{"text":"水、トマトペースト、ローリエ、大まかに切ったキャベツを加え、蓋をして具材がくたくたになるまで煮込む（最低30分）。時間が許せば、水と少し足しつつダラダラと煮込むことで、より一層美味しくなります。"},{"text":"火からおろし、好みで水切りヨーグルトを添えていただく。"}]',NULL,'["uploads/064fc2d8-3904-42f4-b6b1-0d057258a410-1000006125.jpg","867496a2-8944-433a-8e94-590a3379d441/bb50277b-14dc-4804-b3c7-2c880a5087ab-1000006126.jpg"]','{"name":"言ったもん勝ちボルシチ","cookingMode":"DINNER","prepTime":"PT15M","cookTime":"PT30M","images":["uploads/064fc2d8-3904-42f4-b6b1-0d057258a410-1000006125.jpg"],"recipeIngredient":[{"name":"牛かたまり肉 100g"},{"name":"ニンニク (薄切り) 5g"},{"name":"バター 10g"},{"name":"薄切り野菜（玉ネギ必須、にんじん、大根、セロリなど） 計200g"},{"name":"塩 4g"},{"name":"黒コショウ 適量"},{"name":"水 300g"},{"name":"トマトペースト 18g"},{"name":"ローリエ 1枚"},{"name":"キャベツ (大まかに切る) 100g"}],"recipeInstructions":[{"text":"鍋に牛かたまり肉、薄切りにしたニンニク、バター、薄切りにした野菜（玉ネギ、にんじん、大根、セロリなど）、塩、黒コショウを全て入れ、中火にかける。"},{"text":"肉の表面の色が変わり、野菜がしんなりするまで炒める。（ヒント：もし面倒であればこの炒める工程は省略しても良いが、炒めるとコクが出ます。）"},{"text":"水、トマトペースト、ローリエ、大まかに切ったキャベツを加え、蓋をして具材がくたくたになるまで煮込む（最低30分）。時間が許せば、水と少し足しつつダラダラと煮込むことで、より一層美味しくなります。"},{"text":"火からおろし、好みで水切りヨーグルトを添えていただく。"}],"notes":""}',replace('煮込み時間は45分くらいがベストかも\n2026/5はスペアリブで作った','\n',char(10)),1778302642,1778916213);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('79490ed4-c96c-4dfc-8241-b590dfd591d8','メカジキのバタポンソテー','DINNER',NULL,'PT5M','PT9M','{"name":"Infant"}',0,NULL,'[{"name":"メカジキ 2切れ "},{"name":"塩適量"},{"name":"薄力粉小さじ2"},{"name":"油 適量"},{"name":"バター 4g"},{"name":"ポン酢 大さじ1"}]','[{"text":"メカジキをレンジで解凍し、塩を振って出てきた水気を拭き取り、薄く小麦粉をまぶします。"},{"text":"フライパンに油を2〜3g入れ、十分に予熱します。"},{"text":"バターを加え、火加減3でメカジキを3分焼きます。"},{"text":"裏返して蓋をし、火加減2で3分焼きます。"},{"text":"火を消し、蓋をしたまま3分待ちます。"},{"text":"バター10g とポン酢。大さじ1.5をフライパンでちょっと煮詰めてソースとする"}]',NULL,'["79490ed4-c96c-4dfc-8241-b590dfd591d8/703e2f97-4d98-41c7-a32f-52a0f42b80d6-1000006602.jpg"]','{"name":"メカジキのバタポンソテー","cookingMode":"DINNER","prepTime":"PT5M","cookTime":"PT9M","suitableForKids":{"name":"Infant"},"recipeIngredient":[{"name":"メカジキ 2切れ "},{"name":"塩適量"},{"name":"油 適量"},{"name":"バター 10g"},{"name":"ポン酢 大さじ1"}],"recipeInstructions":[{"text":"メカジキをレンジで解凍し、塩を振って出てきた水気を拭き取り、薄く小麦粉をまぶします。"},{"text":"フライパンに油を2〜3g入れ、十分に予熱します。"},{"text":"バターを加え、火加減3でメカジキを3分焼きます。"},{"text":"裏返して蓋をし、火加減2で3分焼きます。"},{"text":"火を消し、蓋をしたまま3分待ちます。"},{"text":"器に盛り付け、ポン酢をかけてお召し上がりください。"}],"notes":""}',replace('は、歌丸のタラのムニエルのレシピ\nソースはしっかり目に煮詰めるとうまいかも？','\n',char(10)),1778317569,1778328136);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('ef1ffde8-a905-40e9-b280-57f419a2b0c5','パプリカのグリル','DINNER',NULL,'PT10M','PT10M','{"name":"Children"}',0,NULL,'[{"name":"パプリカ 2個"},{"name":"塩 小さじ1/2"},{"name":"米油 (またはサラダ油) 小さじ1"}]','[{"text":"パプリカは縦に2cm幅に切ってポリ袋に入れ、塩と米油を加えてなじませる。"},{"text":"アルミホイルに並べて魚焼きグリルまたはトースターで焼き目がつくまで焼く。"}]',NULL,'["uploads/33d48a76-5ab9-4d35-999d-6ff34254df51-1000006603.jpg"]','{"name":"パプリカのグリル","cookingMode":"DINNER","prepTime":"PT10M","cookTime":"PT10M","suitableForKids":{"name":"Children"},"images":["uploads/33d48a76-5ab9-4d35-999d-6ff34254df51-1000006603.jpg"],"recipeIngredient":[{"name":"パプリカ 2個"},{"name":"塩 小さじ1/2"},{"name":"米油 (またはサラダ油) 小さじ1"}],"recipeInstructions":[{"text":"パプリカは縦に2cm幅に切ってポリ袋に入れ、塩と米油を加えてなじませる。"},{"text":"アルミホイルに並べて魚焼きグリルまたはトースターで焼き目がつくまで焼く。"}],"notes":""}',NULL,1778317945,1778317945);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('b4707611-59b0-4d6c-b799-bed884749bad','ごぼうぎっしりメンチカツ','DINNER',NULL,'PT40M','PT10M','{"name":"Child"}',0,NULL,'[{"name":"合挽肉 200g"},{"name":"塩 ひとつまみ"},{"name":"卵 1個 (A)"},{"name":"パン粉 大さじ2 (A)"},{"name":"ケチャップ 大さじ1 (A)"},{"name":"中濃ソース 大さじ1 (A)"},{"name":"ごぼう 1/2本"},{"name":"卵 1個 (衣用B)"},{"name":"小麦粉 大さじ2:18g (衣用B)"},{"name":"パン粉 適量 (衣用)"},{"name":"揚げ油 適量"}]','[{"text":"ごぼうは皮の表面の汚れを水で落とし、細かいささがきにする。"},{"text":"フライパンに油をひき中火で熱し、ごぼうを炒め、色づいてしんなりしたら粗熱を取る。"},{"text":"衣用のBを準備しておく。卵と小麦を混ぜ合わせるボールが1つと、パン粉のボールが1つ"},{"text":"ボウルに冷蔵庫から出したばかりの合挽肉と塩を入れ、手早く混ぜて粘りを出す。そこへA（卵、パン粉、ケチャップ、中濃ソース）とごぼうを入れてよく混ぜたら、10等分にして丸く成形する。"},{"text":"混ぜておいたB（衣用の卵と小麦粉）にくぐらせてから衣用のパン粉をまぶす。"},{"text":"フライパンに高さ2cmの油を入れ中温に熱し、タネを入れて時々返しながら約5分揚げる。"}]',NULL,'["uploads/2c51e4ed-bdf9-42e5-bfb7-be09cfdaa354-1000006611.jpg"]','{"name":"ごぼうぎっしりメンチカツ","cookingMode":"DINNER","prepTime":"PT15M","cookTime":"PT5M","suitableForKids":{"name":"Child"},"recipeYield":{"value":3,"unit":"食分"},"images":["uploads/2c51e4ed-bdf9-42e5-bfb7-be09cfdaa354-1000006611.jpg"],"recipeIngredient":[{"name":"合挽肉 200g"},{"name":"塩 ひとつまみ"},{"name":"卵 1個 (A)"},{"name":"パン粉 大さじ2 (A)"},{"name":"ケチャップ 大さじ1 (A)"},{"name":"中濃ソース 大さじ1 (A)"},{"name":"ごぼう 1/2本"},{"name":"卵 1個 (衣用B)"},{"name":"小麦粉 大さじ2 (衣用B)"},{"name":"パン粉 適量 (衣用)"},{"name":"揚げ油 適量"}],"recipeInstructions":[{"text":"ごぼうは皮の表面の汚れを水で落とし、細かいささがきにする。"},{"text":"フライパンに油をひき中火で熱し、ごぼうを炒め、色づいてしんなりしたら粗熱を取る。"},{"text":"ボウルに冷蔵庫から出したばかりの合挽肉と塩を入れ、手早く混ぜて粘りを出す。そこへA（卵、パン粉、ケチャップ、中濃ソース）とごぼうを入れてよく混ぜたら、10等分にして丸く成形する。"},{"text":"混ぜておいたB（衣用の卵と小麦粉）にくぐらせてから衣用のパン粉をまぶす。"},{"text":"フライパンに高さ2cmの油を入れ中温に熱し、タネを入れて時々返しながら約5分揚げる。"}],"notes":""}',replace('うまい。ごぼうが香ばしい\nごぼうはピーラーで薄くするのがおすすめ。そして短めにすると食べやすいのではないかと、、、\nなんなら痛めた後にハサミでちょくちょく切ってもいいのかもしんない\n\n整形は難しめだけど、がんばる。\n数が多くなってもいいから、唐揚げくらいのサイズ感に抑える。（中までしっかり火を通すため）\n\n2026年5月10日アキラはずっともぐもぐしないと食べれないから、あんまり好きじゃないみたい。1年後くらいに作るかな','\n',char(10)),1778393393,1778412194);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('37d24492-04dd-4d9d-a1eb-eed810f999e5','鯖缶キーマカレー','["MAKE_AHEAD","LUNCH"]',NULL,'PT15M','PT10M',NULL,0,NULL,'[{"name":"鯖の水煮缶 4缶"},{"name":"玉ねぎ 2個"},{"name":"長ネギ 2本"},{"name":"ピーマン 1袋"},{"name":"しいたけ 1袋"},{"name":"生姜 1袋"},{"name":"ホールトマト1缶"},{"name":"シンプルパウダー 16g"},{"name":"マスタードシード 4g"},{"name":"クミンシード 6g"},{"name":"ガーリックペッパー 5振り"},{"name":"塩 6g"},{"name":"水 適量"}]','[{"text":"フライパンに油をひき、マスタードシードとクミンシードなどのホールスパイスを炒める。"},{"text":"ホールスパイスの香りが立ったら、玉ねぎ、長ネギ、ピーマン、しいたけ、生姜などの野菜を加えて炒める。"},{"text":"野菜がしんなりしたら、シンプルパウダー、ホールトマト、鯖の水煮缶（汁ごと）、塩、少量の水を加える。"},{"text":"鯖の身を軽くほぐしながら、5分から10分程度煮込む。水分が少なくなるように水の量を調整し、煮詰めて完成。"}]',NULL,'["37d24492-04dd-4d9d-a1eb-eed810f999e5/d7d8ebb7-84ff-49a6-847b-7c8d888643c1-1000007577.png"]','{"name":"鯖缶キーマカレー","cookingMode":"DINNER","prepTime":"PT15M","cookTime":"PT10M","recipeIngredient":[{"name":"鯖の水煮缶 1缶"},{"name":"玉ねぎ 半分"},{"name":"長ネギ 1本"},{"name":"ピーマン 1個"},{"name":"しいたけ 3個"},{"name":"生姜 適量"},{"name":"ホールトマト 100g"},{"name":"シンプルパウダー 4g"},{"name":"マスタードシード 1g"},{"name":"クミンシード 1g"},{"name":"ガーリックペッパー 5振り"},{"name":"塩 2.0g"},{"name":"水 適量"}],"recipeInstructions":[{"text":"フライパンに油をひき、マスタードシードとクミンシードなどのホールスパイスを炒める。"},{"text":"ホールスパイスの香りが立ったら、玉ねぎ、長ネギ、ピーマン、しいたけ、生姜などの野菜を加えて炒める。"},{"text":"野菜がしんなりしたら、シンプルパウダー、ホールトマト、鯖の水煮缶（汁ごと）、塩、少量の水を加える。"},{"text":"鯖の身を軽くほぐしながら、5分から10分程度煮込む。水分が少なくなるように水の量を調整し、煮詰めて完成。"}],"notes":""}',replace('生姜は絶対にいれる\n入れないと臭い。\n\nホールトマトはトマトペーストでいいかもしれない。ホールトマトだと大量に作る時は水分が残りすぎちゃうので、次から作り置きの時はトマトペーストで作る','\n',char(10)),1778721379,1785541864);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('6b938edf-067b-4056-b7f2-4faa8af37890','パン屋さんランチ','LUNCH',NULL,NULL,NULL,NULL,0,NULL,'[{"name":"なし"}]','[{"text":"パン屋でパンを買う"}]',NULL,'[]','{"name":"パン屋さんランチ","cookingMode":"LUNCH","recipeCategory":"","tags":[],"prepTime":"","cookTime":"","url":"","images":[],"recipeIngredient":[{"name":"なし"}],"recipeInstructions":[{"text":"パン屋でパンを買う"}],"notes":""}',NULL,1778892575,1778892575);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('4225d499-0af0-4ebd-87de-1d151f25fe63','いり鶏（筑前煮）','MAKE_AHEAD',NULL,NULL,'PT25M',NULL,0,NULL,'[{"name":"カット鶏もも肉 450g"},{"name":"干ししいたけ 5枚"},{"name":"ごぼう 1本"},{"name":"れんこん  220g"},{"name":"にんじん 1.5本"},{"name":"ゆでたけのこ 200g"},{"name":"こんにゃく 大きめ1枚"},{"name":"だし カップ4"},{"name":"砂糖 大さじ3"},{"name":"しょうゆ 大さじ3"},{"name":"みりん 大さじ1.5"},{"name":"酒 大さじ1.5"},{"name":"サラダ油"}]','[{"text":"干ししいたけは少なめの水に30分間～1時間つけてゆっくり戻す。軽く水けを絞り、軸を取って四つ割りにする。"},{"text":"れんこんは皮を剥く（革のブツブツが子供は気持ち悪いんだって）"},{"text":"ごぼうは皮をむいて1.5cm幅の斜め切りにし、水にさらして水けをよくきる。れんこんは皮をむいて1.5～2cm幅の半月形またはいちょう形に切り、水にさらして水けをきる。にんじんは皮をむき、1.5cm幅の輪切りまたは半月形に切る。ゆでたけのこは、下部は1cm幅の半月形またはいちょう形、上部はくし形に切る。"},{"text":"こんにゃくは小さめの一口大にちぎり、ゆでてアクを抜く。"},{"text":"鶏肉は一口大に切る。"},{"text":"小鍋に【A】を合わせて火にかけ、ひと煮立ちしたら火を止める。"},{"text":"深めのフライパンにサラダ油大さじ1を熱し、鶏肉を焼きつけるように炒める。焼き色がついたら、ごぼう、こんにゃく、干ししいたけ、たけのこ、にんじんを順に加え、サラダ油大さじ1を加えながら炒め、5を加える。"},{"text":"煮立ったらアクを取って落としぶたをし、中火で約5分間煮る。れんこんを加え、さらに5分間ほど煮、煮汁が少なくなったら火を止め、そのままおいて味を含ませる。"}]','https://www.kyounoryouri.jp/recipe/19213_%E3%81%84%E3%82%8A%E9%B6%8F.html','["4225d499-0af0-4ebd-87de-1d151f25fe63/e33ffe94-af32-4a5a-99fb-956ad04a366b-1000006673.jpg"]','{"name":"いり鶏（筑前煮）","cookingMode":"MAKE_AHEAD","tags":["栗原はるみ"],"cookTime":"PT25M","url":"https://www.kyounoryouri.jp/recipe/19213_%E3%81%84%E3%82%8A%E9%B6%8F.html","recipeIngredient":[{"name":"鶏もも肉 1枚"},{"name":"干ししいたけ 3枚"},{"name":"ごぼう 1本（120g）"},{"name":"れんこん 1～2節（220g）"},{"name":"にんじん 1本（150g）"},{"name":"ゆでたけのこ 1コ（150g）"},{"name":"こんにゃく 1枚（270g）"},{"name":"だし カップ1+1/2"},{"name":"砂糖 大さじ4"},{"name":"しょうゆ 大さじ4"},{"name":"みりん 大さじ2"},{"name":"酒 大さじ2"},{"name":"サラダ油"}],"recipeInstructions":[{"text":"干ししいたけは少なめの水に30分間～1時間つけてゆっくり戻す。軽く水けを絞り、軸を取って四つ割りにする。"},{"text":"ごぼうは皮をむいて1.5cm幅の斜め切りにし、水にさらして水けをよくきる。れんこんは皮をむいて1.5～2cm幅の半月形またはいちょう形に切り、水にさらして水けをきる。にんじんは皮をむき、1.5cm幅の輪切りまたは半月形に切る。ゆでたけのこは、下部は1cm幅の半月形またはいちょう形、上部はくし形に切る。"},{"text":"こんにゃくは小さめの一口大にちぎり、ゆでてアクを抜く。"},{"text":"鶏肉は一口大に切る。"},{"text":"小鍋に【A】を合わせて火にかけ、ひと煮立ちしたら火を止める。"},{"text":"深めのフライパンにサラダ油大さじ1を熱し、鶏肉を焼きつけるように炒める。焼き色がついたら、ごぼう、こんにゃく、干ししいたけ、たけのこ、にんじんを順に加え、サラダ油大さじ1を加えながら炒め、5を加える。"},{"text":"煮立ったらアクを取って落としぶたをし、中火で約5分間煮る。れんこんを加え、さらに5分間ほど煮、煮汁が少なくなったら火を止め、そのままおいて味を含ませる。"}],"notes":""}','れんこん入れるの最後なんだって！',1778912714,1783677258);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('26de8af8-ffe9-4763-9b67-7fcbc4dde9af','チリコンカン（ごはんさんver）','MAKE_AHEAD',NULL,'PT10M','PT25M','{"name":"Infant"}',0,NULL,'[{"name":"ミックスビーンズ 200g"},{"name":"玉ねぎ 1個"},{"name":"にんじん 2本"},{"name":"トマト 2個"},{"name":"豚挽肉 300g"},{"name":"オリーブオイル 大さじ2"},{"name":"ケチャップ 大さじ4"},{"name":"ウスターソース 大さじ4"},{"name":"カレー粉 小さじ1"},{"name":"洋風スープの素 (顆粒) 小さじ2"},{"name":"塩こしょう 適量"}]','[{"text":"玉ねぎ、にんじん、トマトを8mmの角切りにする"},{"text":"フライパンにオリーブオイルをひき、中火で熱し、挽肉と玉ねぎを炒める。途中で塩を加えて、挽肉を色が変わるまで炒める"},{"text":"にんじんとトマト、ミックスビーンズを入れて軽く混ぜたら蓋をして弱火で約15分蒸す"},{"text":"野菜類が柔らかくなったら、A（ケチャップ、ウスターソース、カレー粉、洋風スープの素）を入れて水分を飛ばすようにして炒め、塩こしょうで味を整える"}]',NULL,'["uploads/b3191185-e0dd-470b-bd02-b7b77fce820d-1000006653.jpg"]','{"name":"チリコンカン（ごはんさんver）","cookingMode":"MAKE_AHEAD","tags":["ごはんさん"],"prepTime":"PT10M","cookTime":"PT25M","suitableForKids":{"name":"Infant"},"images":["uploads/b3191185-e0dd-470b-bd02-b7b77fce820d-1000006653.jpg"],"recipeIngredient":[{"name":"ミックスビーンズ 100g"},{"name":"玉ねぎ 1個"},{"name":"にんじん 2本"},{"name":"トマト 2個"},{"name":"豚挽肉 300g"},{"name":"オリーブオイル 大さじ2"},{"name":"ケチャップ 大さじ4"},{"name":"ウスターソース 大さじ4"},{"name":"カレー粉 小さじ1"},{"name":"洋風スープの素 (顆粒) 小さじ2"},{"name":"塩こしょう 適量"}],"recipeInstructions":[{"text":"玉ねぎ、にんじん、トマトを8mmの角切りにする"},{"text":"フライパンにオリーブオイルをひき、中火で熱し、挽肉と玉ねぎを炒める。途中で塩を加えて、挽肉を色が変わるまで炒める"},{"text":"にんじんとトマト、ミックスビーンズを入れて軽く混ぜたら蓋をして弱火で約15分蒸す"},{"text":"野菜類が柔らかくなったら、A（ケチャップ、ウスターソース、カレー粉、洋風スープの素）を入れて水分を飛ばすようにして炒め、塩こしょうで味を整える"}],"notes":""}','',1778913523,1779184134);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('17474afa-8a5c-41e4-8948-32fcb6449afa','サバ大根','MAKE_AHEAD',NULL,NULL,'PT13M',NULL,0,NULL,'[{"name":"さば水煮缶 2-3缶（大根の量で調整）"},{"name":"大根 1本 (約200g)"},{"name":"しょうが 2かけ"},{"name":"酒 大さじ2"},{"name":"しょうゆ 大さじ2（を基準に塩分量適量になるように調整）"},{"name":"水 2カップ"}]','[{"text":"鍋にさば缶の汁と大根、酒、水2カップを入れて火にかけ、ふたをして10分ほど煮る。"},{"text":"大根がやわらかくなったら、しょうがと、さばを加える。"},{"text":"しょうゆをまわしかけてさらに3分ほど煮て、味をなじませる。"}]',NULL,'["uploads/2a2ee19f-d6fc-4b04-9703-e788f62199c0-1000006661.png"]','{"name":"サバ大根","cookingMode":"MAKE_AHEAD","cookTime":"PT13M","images":["uploads/2a2ee19f-d6fc-4b04-9703-e788f62199c0-1000006661.png"],"recipeIngredient":[{"name":"さば水煮缶 1缶"},{"name":"大根 小1/3本 (約200g)"},{"name":"しょうが 小1かけ (約10g)"},{"name":"酒 大さじ1"},{"name":"しょうゆ 大さじ1"},{"name":"水 2カップ"}],"recipeInstructions":[{"text":"鍋にさば缶の汁と大根、酒、水2カップを入れて火にかけ、ふたをして10分ほど煮る。"},{"text":"大根がやわらかくなったら、しょうがと、さばを加える。"},{"text":"しょうゆをまわしかけてさらに3分ほど煮て、味をなじませる。"}],"notes":""}','',1778916323,1779002901);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('9d7ed8f0-071e-4678-a498-d599183dfaab','ふわふわ卵のオムライス','DINNER',NULL,'PT20M','PT25M','{"name":"Infant"}',0,NULL,'[{"name":"ごはん 2合くらい"},{"name":"鶏もも肉 150g"},{"name":"玉ねぎ 1個 "},{"name":"にんじん 2/3本"},{"name":"ピーマン 2個 (10g)"},{"name":"卵 5個 (子供用1個、大人用3～4個)"},{"name":"水 大さじ3 (子供用大さじ1、大人用大さじ2)"},{"name":"塩 少々"},{"name":"トマトケチャップ 大さじ3 "},{"name":"コンソメ (顆粒) 小さじ1"},{"name":"砂糖 小さじ1/2"},{"name":"バター 15g"},{"name":"米油 (またはサラダ油) 適量"},{"name":"トマトケチャップ (仕上げ用) 適宜"}]','[{"text":"玉ねぎ、にんじん、ピーマンはみじん切りにする。"},{"text":"鶏肉は1cmの角切りにする。"},{"text":"フライパンに米油をひき、玉ねぎ、にんじん、ピーマンを入れて炒め、しんなりとしたら鶏肉を加えて、肉に火を通します。"},{"text":"手順①にA（トマトケチャップ大さじ2、コンソメ顆粒小さじ1/2、砂糖小さじ1/2、塩ひとつまみ）を入れて弱火で1分ほど炒めます。"},{"text":"手順②にごはんを入れて全体をなじませます。"},{"text":"子ども用90gほど×2食分をとりわけます。大人用2食分は残りのフライパンに追加調味料（トマトケチャップ大さじ1、コンソメ顆粒小さじ1/2、塩少々）を入れて再度炒め合わせ、それぞれ器に盛ります。"},{"text":"適当に卵に包む"}]',NULL,'["uploads/ca95b138-57c0-450a-ab22-d78c77776086-1000006663.jpg"]','{"name":"ふわふわ卵のオムライス","cookingMode":"DINNER","prepTime":"PT20M","cookTime":"PT25M","suitableForKids":{"name":"Infant"},"images":["uploads/ca95b138-57c0-450a-ab22-d78c77776086-1000006663.jpg"],"recipeIngredient":[{"name":"ごはん 400g"},{"name":"鶏もも肉 1/3枚 (80g)"},{"name":"玉ねぎ 1/4個 (50g)"},{"name":"にんじん 1/5本 (30g)"},{"name":"ピーマン 1/3個 (10g)"},{"name":"卵 4～5個 (子供用1個、大人用3～4個)"},{"name":"水 大さじ3 (子供用大さじ1、大人用大さじ2)"},{"name":"塩 少々"},{"name":"トマトケチャップ 大さじ3 (A用大さじ2、追加調味料大さじ1)"},{"name":"コンソメ (顆粒) 小さじ1 (A用小さじ1/2、追加調味料小さじ1/2)"},{"name":"砂糖 小さじ1/2"},{"name":"バター 15g (子供用卵に5g、大人用卵に10g)"},{"name":"米油 (またはサラダ油) 適量"},{"name":"ドライパセリ 適宜"},{"name":"トマトケチャップ (仕上げ用) 適宜"}],"recipeInstructions":[{"text":"玉ねぎ、にんじん、ピーマンはみじん切りにする。"},{"text":"鶏肉は1cmの角切りにする。"},{"text":"フライパンに米油をひき、玉ねぎ、にんじん、ピーマンを入れて炒め、しんなりとしたら鶏肉を加えて、肉に火を通します。"},{"text":"手順①にA（トマトケチャップ大さじ2、コンソメ顆粒小さじ1/2、砂糖小さじ1/2、塩ひとつまみ）を入れて弱火で1分ほど炒めます。"},{"text":"手順②にごはんを入れて全体をなじませます。"},{"text":"子ども用90gほど×2食分をとりわけます。大人用2食分は残りのフライパンに追加調味料（トマトケチャップ大さじ1、コンソメ顆粒小さじ1/2、塩少々）を入れて再度炒め合わせ、それぞれ器に盛ります。"},{"text":"きれいにしたフライパンにバター5gを入れて火にかけ、混ぜ合わせたB（卵1個、水大さじ1、塩少々）を入れて炒り卵を作ります。子ども用の器に半量ずつのせ、お好みでパセリを散らします。"},{"text":"フライパンにバター10gを入れて火にかけ、混ぜ合わせたC（卵3～4個、水大さじ2、塩ひとつまみ）を半量入れて半熟卵を作り、大人用の器にのせます。残りも同様に焼いてもうひとつ作り、お好みでトマトケチャップをかけます。"}],"notes":""}','',1778920167,1785022400);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('cf460a02-0905-4348-b987-fe1af16890cd','クラムチャウダー','["MAKE_AHEAD"]',NULL,'PT15M','PT20M',NULL,0,NULL,'[{"name":"ベース野菜MIX 300g"},{"name":"厚切りベーコン (1cm幅に切る) 90g"},{"name":"アサリ水煮缶 125g (3缶、汁ごと)"},{"name":"じゃがいも (角切り) 300g (2/3個)"},{"name":"水 100ml"},{"name":"牛乳 600ml"},{"name":"バター 30g"},{"name":"塩 2g"},{"name":"クラッカー 56g"},{"name":"ローレル 3枚"},{"name":"タイム 3枝"},{"name":"ナツメグパウダー 1.0g"},{"name":"ブラックペッパーパウダー 0.5g"},{"name":"パセリ (粗みじん切り) お好みで適量"}]','[{"text":"鍋にバターを熱し、ベース野菜MIX、厚切りベーコンをさっと炒め、蓋をして弱火で15分ほど蒸し煮にします。焦げ付きそうになったら分量外の水を少量足す。"},{"text":"玉ねぎが完全に柔らかくなったら、アサリ水煮缶、じゃがいも、水、ローレル、タイム、ナツメグを加えます。沸騰したら蓋をして5分ほど煮込みます。"},{"text":"じゃがいもが柔らかくなったら牛乳と塩、なるべく細かく砕いたクラッカーを加え、沸騰してとろみが付くまで混ぜながら煮込みます。器に盛り、ブラックペッパーとお好みでパセリを散らし、分量外のクラッカーを添えます。クラッカーがない場合は小麦粉でとろみをつけてもOKです。"}]',NULL,'["uploads/2bcc3eed-fc4e-44e9-ace8-2bc5b112a978-1000006674.jpg"]','{"name":"クラムチャウダー","cookingMode":"DINNER","prepTime":"PT15M","cookTime":"PT20M","images":["uploads/2bcc3eed-fc4e-44e9-ace8-2bc5b112a978-1000006674.jpg"],"recipeIngredient":[{"name":"ベース野菜MIX 300g"},{"name":"厚切りベーコン (1cm幅に切る) 90g"},{"name":"アサリ水煮缶 125g (3缶、汁ごと)"},{"name":"じゃがいも (角切り) 300g (2/3個)"},{"name":"水 100ml"},{"name":"牛乳 600ml"},{"name":"バター 30g"},{"name":"塩 2g"},{"name":"クラッカー 56g"},{"name":"ローレル 3枚"},{"name":"タイム 3枝"},{"name":"ナツメグパウダー 1.0g"},{"name":"ブラックペッパーパウダー 0.5g"},{"name":"パセリ (粗みじん切り) お好みで適量"}],"recipeInstructions":[{"text":"鍋にバターを熱し、ベース野菜MIX、厚切りベーコンをさっと炒め、蓋をして弱火で15分ほど蒸し煮にします。焦げ付きそうになったら分量外の水を少量足し、じゃがいもが完全に柔らかくなるまで火を通します。"},{"text":"玉ねぎが完全に柔らかくなったら、アサリ水煮缶、じゃがいも、水、ローレル、タイム、ナツメグを加えます。沸騰したら蓋をして5分ほど煮込みます。"},{"text":"じゃがいもが柔らかくなったら牛乳と塩、なるべく細かく砕いたクラッカーを加え、沸騰してとろみが付くまで混ぜながら煮込みます。器に盛り、ブラックペッパーとお好みでパセリを散らし、分量外のクラッカーを添えます。クラッカーがない場合は小麦粉でとろみをつけてもOKです。"}],"notes":""}','あさり水煮缶をケチる場合はツナ缶に置き換えるとか。あとは鶏もも肉を入れるのもおすすめ。とはいえ、アサリ水煮缶は1缶は入れたい',1778993692,1785541989);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('56100d33-df38-4c06-a7b2-7787d5e1115f','ミニマルコールスロー','LUNCH',NULL,'PT10M','PT20M',NULL,0,NULL,'[{"name":"キャベツ 100g"},{"name":"塩 0.5g"},{"name":"酢 5g"},{"name":"サラダ油 10g"}]','[{"text":"キャベツは、軸と葉に切り分ける。"},{"text":"葉は重ねてひとかたまりにして切る。"},{"text":"軸は斜め薄切りにする。"},{"text":"キャベツとその他の材料を混ぜる。"}]',NULL,'["uploads/3e29f35c-c749-49d8-9092-f777000ae45c-1000006689.jpg"]','{"name":"ミニマルコールスロー","cookingMode":"LUNCH","prepTime":"PT10M","cookTime":"PT20M","images":["uploads/3e29f35c-c749-49d8-9092-f777000ae45c-1000006689.jpg"],"recipeIngredient":[{"name":"キャベツ 100g"},{"name":"塩 1g"},{"name":"酢 5g"},{"name":"サラダ油 10g"}],"recipeInstructions":[{"text":"キャベツは、軸と葉に切り分ける。"},{"text":"葉は重ねてひとかたまりにして切る。"},{"text":"軸は斜め薄切りにする。"},{"text":"キャベツとその他の材料を混ぜる。"}],"notes":""}','',1779161535,1779184124);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('ccb28445-168b-486b-ae60-eb71041ea967','スパニッシュオムレツ','MAKE_AHEAD',NULL,NULL,NULL,NULL,0,NULL,'[{"name":"卵6個"},{"name":"玉ねぎ1個"},{"name":"じゃがいも2個"},{"name":"ピーマン1個"},{"name":"人参半分"},{"name":"三和特製パックに入った薄切りベーコン 1パック（200gくらい？）"},{"name":"ピザ用チーズ 40g"}]','[{"text":"ピーマンと人参はみじん切りにする\n玉ねぎとじゃがいもは薄切りにする"},{"text":"まずは玉ねぎとじゃがいもを油多めでじっくり炒める"},{"text":"そこにピーマン人参を追加して炒める"},{"text":"卵を溶いてその中に炒めた野菜たちを入れる"},{"text":"ティファールの22cm のフライパンで焼く火力3で5分26cm のフライパンにひっくり返して、また火力3で5分蓋をする"}]',NULL,'[]','{"name":"スパニッシュオムレツ","cookingMode":"MAKE_AHEAD","recipeCategory":"","tags":[],"prepTime":"","cookTime":"","url":"","images":[],"recipeIngredient":[{"name":"卵6個"},{"name":"玉ねぎ1個"},{"name":"じゃがいも2個"},{"name":"ピーマン1個"},{"name":"人参半分"},{"name":"三和のベーコン"},{"name":"ピザ用チーズ"}],"recipeInstructions":[{"text":"ピーマンと人参はみじん切りにする\n玉ねぎとじゃがいもは薄切りにする"},{"text":"まずは玉ねぎとじゃがいもを油多めでじっくり炒める"},{"text":"そこにピーマン人参を追加して炒める"},{"text":"卵を溶いてその中に炒めた野菜たちを入れる"},{"text":"ティファールの22cm のフライパンで焼く火力3で5分26cm のフライパンにひっくり返して、また火力3で5分蓋をする"}],"notes":""}','2026/05あきらはそんなに食べなかった',1779512315,1780126873);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('5fbf42dc-14e4-49f2-be46-98d9d379f413','野菜たっぷり！定番ハンバーグ','DINNER',NULL,'PT15M','PT15M','{"name":"Children"}',0,NULL,'[{"name":"牛豚合いびき肉 300g"},{"name":"玉ねぎ 1/2個 (100g)"},{"name":"にんじん 1/3本 (50g)"},{"name":"ピーマン 1個 (35g)"},{"name":"しいたけ 1個 (20g)"},{"name":"パン粉 大さじ3"},{"name":"牛乳 大さじ3"},{"name":"卵 1個 (または豆腐 50g)"},{"name":"コンソメ (顆粒) 小さじ1/2"},{"name":"塩 小さじ1/2"},{"name":"トマトケチャップ 小さじ2 (ハンバーグ用)"},{"name":"ごま油 適量"},{"name":"【大人用ソース】赤ワイン 大さじ2 (または酒でも可)"},{"name":"【大人用ソース】トマトケチャップ 大さじ2"},{"name":"【大人用ソース】中濃ソース 大さじ1 (またはウスターソースでも可)"},{"name":"【大人用ソース】しょうゆ 大さじ1"},{"name":"【大人用ソース】砂糖 大さじ1"},{"name":"【子ども用ソース】トマトケチャップ 適宜"}]','[{"text":"玉ねぎ、にんじん、ピーマン、しいたけをみじん切りにする。"},{"text":"フライパンにごま油をひいて火にかけ、みじん切りにした食材を入れ、しんなりするまで炒めて粗熱を取る。"},{"text":"ボウルにひき肉、粗熱を取った炒め野菜、パン粉、牛乳、卵、コンソメ(顆粒)、塩、トマトケチャップ(小さじ2)を入れて、粘りが出るまでよくこねる。"},{"text":"タネを子ども用に1個60gほどで4個、大人用は残りを2等分して、それぞれ空気を抜きながら形を整える。"},{"text":"ステップ2で使ったフライパンをきれいにし、ごま油をひいて火にかける。成形したハンバーグを並べ、真ん中をくぼませる。"},{"text":"両面に焼き色がついたら、ハンバーグの高さ1/3ほどまで水(分量外)を入れ、フタをして弱めの中火で蒸し焼きにする。"},{"text":"ハンバーグの中心を串などで刺し、透明な肉汁が出て中まで火が通っていることを確認したら、大人用と子ども用を皿に盛り付ける。"},{"text":"ハンバーグを焼いたフライパンに大人用ソースの材料(赤ワイン、トマトケチャップ、中濃ソース、しょうゆ、砂糖)を全て入れ、火にかけて少しとろみがつくまで煮詰める。"},{"text":"大人用ハンバーグに大人用ソースをかけ、子ども用ハンバーグにはお好みでトマトケチャップをかける。"}]',NULL,'["uploads/9d561b4f-2a9c-43a9-8887-7ee180c742de-1000002731.jpg"]','{"name":"野菜たっぷり！定番ハンバーグ","cookingMode":"DINNER","prepTime":"PT15M","cookTime":"PT15M","suitableForKids":{"name":"Children"},"recipeYield":{"value":2,"unit":"食分"},"images":["uploads/9d561b4f-2a9c-43a9-8887-7ee180c742de-1000002731.jpg"],"recipeIngredient":[{"name":"牛豚合いびき肉 300g"},{"name":"玉ねぎ 1/2個 (100g)"},{"name":"にんじん 1/3本 (50g)"},{"name":"ピーマン 1個 (35g)"},{"name":"しいたけ 1個 (20g)"},{"name":"パン粉 大さじ3"},{"name":"牛乳 大さじ3"},{"name":"卵 1個 (または豆腐 50g)"},{"name":"コンソメ (顆粒) 小さじ1/2"},{"name":"塩 小さじ1/2"},{"name":"トマトケチャップ 小さじ2 (ハンバーグ用)"},{"name":"ごま油 適量"},{"name":"【大人用ソース】赤ワイン 大さじ2 (または酒でも可)"},{"name":"【大人用ソース】トマトケチャップ 大さじ2"},{"name":"【大人用ソース】中濃ソース 大さじ1 (またはウスターソースでも可)"},{"name":"【大人用ソース】しょうゆ 大さじ1"},{"name":"【大人用ソース】砂糖 大さじ1"},{"name":"【子ども用ソース】トマトケチャップ 適宜"}],"recipeInstructions":[{"text":"玉ねぎ、にんじん、ピーマン、しいたけをみじん切りにする。"},{"text":"フライパンにごま油をひいて火にかけ、みじん切りにした食材を入れ、しんなりするまで炒めて粗熱を取る。"},{"text":"ボウルにひき肉、粗熱を取った炒め野菜、パン粉、牛乳、卵、コンソメ(顆粒)、塩、トマトケチャップ(小さじ2)を入れて、粘りが出るまでよくこねる。"},{"text":"タネを子ども用に1個60gほどで4個、大人用は残りを2等分して、それぞれ空気を抜きながら形を整える。"},{"text":"ステップ2で使ったフライパンをきれいにし、ごま油をひいて火にかける。成形したハンバーグを並べ、真ん中をくぼませる。"},{"text":"両面に焼き色がついたら、ハンバーグの高さ1/3ほどまで水(分量外)を入れ、フタをして弱めの中火で蒸し焼きにする。"},{"text":"ハンバーグの中心を串などで刺し、透明な肉汁が出て中まで火が通っていることを確認したら、大人用と子ども用を皿に盛り付ける。"},{"text":"ハンバーグを焼いたフライパンに大人用ソースの材料(赤ワイン、トマトケチャップ、中濃ソース、しょうゆ、砂糖)を全て入れ、火にかけて少しとろみがつくまで煮詰める。"},{"text":"大人用ハンバーグに大人用ソースをかけ、子ども用ハンバーグにはお好みでトマトケチャップをかける。"}],"notes":""}',NULL,1780723554,1780723554);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('36933bb5-38f0-49fa-86b9-c0c19e0f77d8','豚バラで作るコクうまポークカレー','["MAKE_AHEAD"]',NULL,'PT10M','PT30M',NULL,0,NULL,'[{"name":"ハウス バーモントカレー＜甘口＞２３０ｇ 1/2箱 115g"},{"name":"豚肉（ばら）（薄切り）  250g"},{"name":"玉ねぎ 中２個 400g"},{"name":"にんじん 1〜1.5本"},{"name":"じゃがいも 3個"},{"name":"トマトケチャップ 小さじ２"},{"name":"はちみつ 大さじ１"},{"name":"サラダ油 小さじ１"},{"name":"水 850ml"}]','[{"text":"＜カレーを作る＞玉ねぎ、にんじん、じゃがいもは小さめの一口大に切る。豚肉は５ｃｍ幅に切り、トマトケチャップをもみ込む。"},{"text":"厚手の鍋にサラダ油を熱し、（１）の豚肉を入れ、肉に焼き色がつくまで炒めたら、じゃがいも以外の具材を入れ、玉ねぎがすき通るまでよく炒める。"},{"text":"水を入れ、沸騰したらあくを取り、はちみつを加えて溶かし、弱火～中火で約１２分煮込む。（１）のじゃがいもを加えてさらに約８分煮込む。"},{"text":"いったん火を止め、ルウを割り入れて溶かし、再び弱火で時々かき混ぜながら、とろみがつくまで約１０分煮込む。"}]','https://housefoods.jp/recipe/rcp_00025463.html',NULL,'{"name":"豚バラで作るコクうまポークカレー","cookingMode":"DINNER","prepTime":"PT10M","cookTime":"PT30M","recipeYield":{"value":3,"unit":"食分"},"url":"https://housefoods.jp/recipe/rcp_00025463.html","recipeIngredient":[{"name":"ハウス バーモントカレー＜甘口＞２３０ｇ 1/2箱 115g"},{"name":"豚肉（ばら）（薄切り）  250g"},{"name":"玉ねぎ 中２個 400g"},{"name":"にんじん 1〜1.5本"},{"name":"じゃがいも 3個"},{"name":"トマトケチャップ 小さじ２"},{"name":"はちみつ 大さじ１"},{"name":"サラダ油 小さじ１"},{"name":"水 850ml"}],"recipeInstructions":[{"text":"＜カレーを作る＞玉ねぎ、にんじん、じゃがいもは小さめの一口大に切る。豚肉は５ｃｍ幅に切り、トマトケチャップをもみ込む。"},{"text":"厚手の鍋にサラダ油を熱し、（１）の豚肉を入れ、肉に焼き色がつくまで炒めたら、じゃがいも以外の具材を入れ、玉ねぎがすき通るまでよく炒める。"},{"text":"水を入れ、沸騰したらあくを取り、はちみつを加えて溶かし、弱火～中火で約１２分煮込む。（１）のじゃがいもを加えてさらに約８分煮込む。"},{"text":"いったん火を止め、ルウを割り入れて溶かし、再び弱火で時々かき混ぜながら、とろみがつくまで約１０分煮込む。"}],"notes":""}','',1780723892,1783752832);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('9f9b72ea-f6bc-4041-8e0c-11cada692089','お米のポタージュ','MAKE_AHEAD',NULL,'PT15M','PT10M','{"name":"Infant"}',0,NULL,'[{"name":"にんじん 1本"},{"name":"パプリカ（赤） 2個"},{"name":"玉ねぎ 2個"},{"name":"炊いたごはん 200g（約0.6号）"},{"name":"水 200cc"},{"name":"牛乳 600cc"},{"name":"塩麹 大さじ2"}]','[{"text":"にんじんは薄く輪切りに、パプリカと玉ねぎは半分に切り縦に薄切りにする"},{"text":"鍋底に塩をひとつまみまぶした後、パプリカ、玉ねぎ、にんじん、ごはんの順に重ねて入れる。上からさらにひとつまみの塩をふり、蓋をして弱火で約10分煮込む"},{"text":"野菜が柔らかくなったら全体を軽く混ぜ、水を加えてフードプロセッサーなどで滑らかになるまで撹拌する"},{"text":"牛乳を入れ、沸騰させないように弱火で温める。最後に塩麹を入れてひと混ぜしたら火を止める"}]',NULL,'["uploads/12f23fbd-fae7-4a8f-929e-b82a3950341f-1000006974.jpg"]','{"name":"お米のポタージュ","cookingMode":"MAKE_AHEAD","prepTime":"PT15M","cookTime":"PT10M","suitableForKids":{"name":"Infant"},"images":["uploads/12f23fbd-fae7-4a8f-929e-b82a3950341f-1000006974.jpg"],"recipeIngredient":[{"name":"にんじん 1本"},{"name":"パプリカ（赤） 2個"},{"name":"玉ねぎ 2個"},{"name":"炊いたごはん 200g"},{"name":"水 200cc"},{"name":"牛乳 600cc"},{"name":"塩麹 大さじ2"}],"recipeInstructions":[{"text":"にんじんは薄く輪切りに、パプリカと玉ねぎは半分に切り縦に薄切りにする"},{"text":"鍋底に塩をひとつまみまぶした後、パプリカ、玉ねぎ、にんじん、ごはんの順に重ねて入れる。上からさらにひとつまみの塩をふり、蓋をして弱火で約10分煮込む"},{"text":"野菜が柔らかくなったら全体を軽く混ぜ、水を加えてフードプロセッサーなどで滑らかになるまで撹拌する"},{"text":"牛乳を入れ、沸騰させないように弱火で温める。最後に塩麹を入れてひと混ぜしたら火を止める"}],"notes":""}','味はすごく美味しい。パプリカか何かが結構食感残ってしまうので、もしかしたら圧力鍋で調理した方が美味しく滑らかになるのかもしれない。それかま、フードプロセッサーとかで潰すべきなのかもしれないけど、ちょっとよくわかんない。',1781332927,1781932623);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('de6e5918-4e2e-4a9b-b58d-926bc061b99e','金時豆の煮方（甘煮）','MAKE_AHEAD',NULL,'PT12H','PT1H',NULL,0,NULL,'[{"name":"金時豆 1袋（250ｇ）"},{"name":"砂糖 80g"},{"name":"塩 0.5g"},{"name":"水（またはゆで汁） 大さじ3"}]','[{"text":"金時豆は一晩ほど水にひたして戻します。ふっくらと戻ったら、下ゆでに入ります。戻した水でそのまま下ゆでに入りますので、たっぷりの水ではじめから鍋の中で戻すとよいです。"},{"text":"金時豆は戻し汁ごと、そのまま火にかけます。沸騰したらゆで汁をすべて捨てて、ざるにあけます（一度ゆでこぼしてアクを抜くのが目的）。"},{"text":"一度ゆでこぼしたら、再度水をたっぷりかぶるくらい加えて火にかけます。2度目は金時豆がしっかり柔らかくなるまで下ゆでします。アクが出てきたら取り除き、弱火にします。ゆでる時間は40分ほどが目安です。ゆで上がった豆を取り出し、指でつまんで簡単につぶれるくらい柔らかくなったらOKです。この下ゆででしっかり柔らかくなるまで火を通すことが大切です。40分ほど煮る間、水気が少なくなったら水を適宜足し入れてください。"},{"text":"豆が柔らかくなったら、（好みで調味料をなじませる用のゆで汁大さじ2を取っておいてから）、ざる上げして汁気を切ります。豆を鍋に戻し入れて、Aの調味料（砂糖大さじ7、塩小さじ1/3、ゆで汁まはた水大さじ2）をすべて加え、全体を軽く混ぜてから弱火にかけます。砂糖が溶けると少し水分も出てくるので、弱火で5～7分ほど時おり混ぜながら煮たら出来上がりです。最後に味見をして、必要なら塩や砂糖を足し入れて、好みの甘みや塩気にしてください。温かい状態でも冷めてからでも、美味しく食べることができます。"}]',NULL,NULL,'{"name":"金時豆の煮方（甘煮）","cookingMode":"MAKE_AHEAD","prepTime":"PT12H","cookTime":"PT1H","recipeIngredient":[{"name":"金時豆 1袋（200ｇ）"},{"name":"砂糖 大さじ7"},{"name":"塩 小さじ1/3"},{"name":"水（またはゆで汁） 大さじ2"}],"recipeInstructions":[{"text":"金時豆は一晩ほど水にひたして戻します。ふっくらと戻ったら、下ゆでに入ります。戻した水でそのまま下ゆでに入りますので、たっぷりの水ではじめから鍋の中で戻すとよいです。"},{"text":"金時豆は戻し汁ごと、そのまま火にかけます。沸騰したらゆで汁をすべて捨てて、ざるにあけます（一度ゆでこぼしてアクを抜くのが目的）。"},{"text":"一度ゆでこぼしたら、再度水をたっぷりかぶるくらい加えて火にかけます。2度目は金時豆がしっかり柔らかくなるまで下ゆでします。アクが出てきたら取り除き、弱火にします。ゆでる時間は40分ほどが目安です。ゆで上がった豆を取り出し、指でつまんで簡単につぶれるくらい柔らかくなったらOKです。この下ゆででしっかり柔らかくなるまで火を通すことが大切です。40分ほど煮る間、水気が少なくなったら水を適宜足し入れてください。"},{"text":"豆が柔らかくなったら、（好みで調味料をなじませる用のゆで汁大さじ2を取っておいてから）、ざる上げして汁気を切ります。豆を鍋に戻し入れて、Aの調味料（砂糖大さじ7、塩小さじ1/3、ゆで汁まはた水大さじ2）をすべて加え、全体を軽く混ぜてから弱火にかけます。砂糖が溶けると少し水分も出てくるので、弱火で5～7分ほど時おり混ぜながら煮たら出来上がりです。最後に味見をして、必要なら塩や砂糖を足し入れて、好みの甘みや塩気にしてください。温かい状態でも冷めてからでも、美味しく食べることができます。"}],"notes":""}','火加減は煮る時は1でいい。1でま蓋を完全に閉めるか。それか様子を見て蓋をちょっと開けるくらいで。それだとまちょっと硬めにも感じたので、もう10分くらい煮る時間を長くしてもいいのかも',1781336704,1784336927);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('ed23d459-11ae-4a3b-9d5b-c0c9eb2cd72b','【鮭フライ☆オーロラソース】子どもも喜ぶお魚レシピ♡','DINNER',NULL,'PT0M','PT10M','{"name":"Children"}',0,NULL,'[{"name":"生鮭 3切れ(200g)"},{"name":"塩こしょう 少々"},{"name":"薄力粉、片栗粉 各大さじ1.5"},{"name":"水 大さじ2"},{"name":"パン粉 適量"},{"name":"マヨネーズ 大さじ2"},{"name":"ケチャップ 大さじ1"},{"name":"砂糖、塩こしょう 少々"}]','[{"text":"生鮭はペーパーで水気を拭き取り、2等分に切って塩こしょうをふる。"},{"text":"合わせたA 薄力粉、片栗粉各大さじ1.5、水大さじ2､パン粉の順で衣付けする。"},{"text":"フライパンに油大さじ3を中火で熱し､②をこんがり揚げ焼きにする。"},{"text":"器に盛り、合わせたB マヨネーズ大さじ2、ケチャップ大さじ1、砂糖、塩こしょう少々をかける。"}]','https://oceans-nadia.com/user/484627/recipe/462885',NULL,'{"name":"【鮭フライ☆オーロラソース】子どもも喜ぶお魚レシピ♡","cookingMode":"DINNER","prepTime":"PT0M","cookTime":"PT10M","suitableForKids":{"name":"Children"},"url":"https://oceans-nadia.com/user/484627/recipe/462885","recipeIngredient":[{"name":"生鮭 3切れ(200g)"},{"name":"塩こしょう 少々"},{"name":"薄力粉、片栗粉 各大さじ1.5"},{"name":"水 大さじ2"},{"name":"パン粉 適量"},{"name":"マヨネーズ 大さじ2"},{"name":"ケチャップ 大さじ1"},{"name":"砂糖、塩こしょう 少々"}],"recipeInstructions":[{"text":"生鮭はペーパーで水気を拭き取り、2等分に切って塩こしょうをふる。"},{"text":"合わせたA 薄力粉、片栗粉各大さじ1.5、水大さじ2､パン粉の順で衣付けする。"},{"text":"フライパンに油大さじ3を中火で熱し､②をこんがり揚げ焼きにする。"},{"text":"器に盛り、合わせたB マヨネーズ大さじ2、ケチャップ大さじ1、砂糖、塩こしょう少々をかける。"}],"notes":""}',NULL,1781347819,1781347819);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('64f3c09b-4057-4b16-b47c-f4cf4d26eca5','シンプルバタークッキー','["LUNCH"]',NULL,'PT75M','PT15M','{"name":"Infant"}',0,NULL,'[{"name":"バター 30g (無塩)"},{"name":"薄力粉 50g （純ココアの場合は、薄力粉45g＋純ココア4g）"},{"name":"粉糖 10g"}]','[{"text":"ボールにA バター30g、薄力粉50g、粉糖10gを入れ、手でバターを潰しながら馴染ませる。ひとかたまりになるまでしっかりと馴染ませ、生地をラップで包み1時間ほど休ませる。（棒状にラップに包んで冷凍してアイスボックスにしてもOK）"},{"text":"お好みの形に成形する。予熱170度で15分焼いて、できあがり。"}]','https://oceans-nadia.com/user/14762/recipe/443285',NULL,'{"name":"シンプルバタークッキー","cookingMode":"MAKE_AHEAD","prepTime":"PT75M","cookTime":"PT15M","suitableForKids":{"name":"Infant"},"recipeYield":{"value":2,"unit":"食分"},"url":"https://oceans-nadia.com/user/14762/recipe/443285","recipeIngredient":[{"name":"バター 30g (無塩)"},{"name":"薄力粉 50g （純ココアの場合は、薄力粉45g＋純ココア4g）"},{"name":"粉糖 10g"}],"recipeInstructions":[{"text":"ボールにA バター30g、薄力粉50g、粉糖10gを入れ、手でバターを潰しながら馴染ませる。ひとかたまりになるまでしっかりと馴染ませ、生地をラップで包み1時間ほど休ませる。（棒状にラップに包んで冷凍してアイスボックスにしてもOK）"},{"text":"お好みの形に成形する。予熱170度で15分焼いて、できあがり。"}],"notes":""}','',1781483340,1783746435);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('58e1fbcb-ad06-4352-9024-e02ba4367651','鶏肉の胡麻味噌焼き','MAKE_AHEAD',NULL,'PT20M','PT20M','{"name":"Infant"}',0,NULL,'[{"name":"鶏もも肉 1枚 (250g)"},{"name":"A 味噌 小さじ1 強"},{"name":"砂糖 小さじ1と1/3"},{"name":"みりん 小さじ1"},{"name":"しょうゆ 小さじ1/2"},{"name":"白いりごま 大さじ1と1/2"}]','[{"text":"鶏肉は1個が20gくらいの大きさに切る。"},{"text":"ポリ袋にAを入れ、1を加えてもみ、冷蔵庫に15分以上おく。白ごまを加えて混ぜる。"},{"text":"オーブンシートを敷いた天板に並べ、200℃に予熱したオーブンで20分ほど (オーブントースターで焼く場合も20分ほど) 焼く。"}]',NULL,'["uploads/2666025d-bfc4-4e6a-a46b-f75b4034492f-1000002733.jpg"]','{"name":"鶏肉の胡麻味噌焼き","cookingMode":"MAKE_AHEAD","prepTime":"PT20M","cookTime":"PT20M","suitableForKids":{"name":"Infant"},"images":["uploads/2666025d-bfc4-4e6a-a46b-f75b4034492f-1000002733.jpg"],"recipeIngredient":[{"name":"鶏もも肉 1枚 (250g)"},{"name":"A 味噌 小さじ1 強"},{"name":"砂糖 小さじ1と1/3"},{"name":"みりん 小さじ1"},{"name":"しょうゆ 小さじ1/2"},{"name":"白いりごま 大さじ1と1/2"}],"recipeInstructions":[{"text":"鶏肉は1個が20gくらいの大きさに切る。"},{"text":"ポリ袋にAを入れ、1を加えてもみ、冷蔵庫に15分以上おく。白ごまを加えて混ぜる。"},{"text":"オーブンシートを敷いた天板に並べ、200℃に予熱したオーブンで20分ほど (オーブントースターで焼く場合も20分ほど) 焼く。"}],"notes":""}',NULL,1781938492,1784336928);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('a430caa5-8829-47dd-bdcf-fad1412c20b3','ミニトマト切っただけ','["LUNCH","DINNER"]',NULL,NULL,NULL,NULL,0,NULL,'[{"name":"ミニトマト"}]','[{"text":"半分に切る"}]',NULL,'[]','{"name":"ミニトマト切っただけ","cookingMode":"MAKE_AHEAD","recipeCategory":"","tags":[],"prepTime":"","cookTime":"","url":"","images":[],"recipeIngredient":[{"name":"ミニトマト"}],"recipeInstructions":[{"text":"半分に切る"}],"notes":""}','',1781939337,1783746371);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('62df799b-ea6e-40a0-96c4-843799b6ebd0','キャベ玉焼き','LUNCH',NULL,'PT10M','PT20M',NULL,0,NULL,'[{"name":"キャベツ (せん切り) 220g ざっくりキャベツ1/4くらい"},{"name":"豚ばら肉 (スライス) 50g"},{"name":"塩 1.3g"},{"name":"こしょう 少々"},{"name":"サラダ油 10g"},{"name":"卵 2個"},{"name":"オーロラソース (マヨネーズとケチャップを同量ずつ軽く混ぜる 10gずつでよい) 適量"}]','[{"text":"小さめのフライパンにキャベツを敷き込み、ひと口大に切った豚肉をのせ、塩、こしょうをして油を回しかける。ふたをして中～弱火にかける。"},{"text":"キャベツに火が通ってしんなりしたら、溶いた卵を上から全体にかける。ふたをして蒸し焼きにする。"},{"text":"卵に大体火が通ったら、ひっくり返して裏面も焼く。仕上げにオーロラソースを塗る。"}]',NULL,'["uploads/20305ca0-2841-4983-bb3d-af2a160e06ed-1000007186.jpg"]','{"name":"キャベ玉焼き","cookingMode":"DINNER","prepTime":"PT10M","cookTime":"PT20M","images":["uploads/20305ca0-2841-4983-bb3d-af2a160e06ed-1000007186.jpg"],"recipeIngredient":[{"name":"キャベツ (せん切り) 220g"},{"name":"豚ばら肉 (スライス) 50g"},{"name":"塩 1.3g"},{"name":"こしょう 少々"},{"name":"サラダ油 10g"},{"name":"卵 2個"},{"name":"オーロラソース (マヨネーズとケチャップを同量ずつ軽く混ぜる 10gずつでよい) 適量"}],"recipeInstructions":[{"text":"小さめのフライパンにキャベツを敷き込み、ひと口大に切った豚肉をのせ、塩、こしょうをして油を回しかける。ふたをして中～弱火にかける。"},{"text":"キャベツに火が通ってしんなりしたら、溶いた卵を上から全体にかける。ふたをして蒸し焼きにする。"},{"text":"卵に大体火が通ったら、ひっくり返して裏面も焼く。仕上げにオーロラソースを塗る。"}],"notes":""}',replace('お好み焼きみたいな見た目だけど、割とあっさりな感じ？\n鶏ガラちょっと入れたらそれっぽくなるかも？','\n',char(10)),1782293064,1782305046);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('caa569de-1c81-43b5-a806-2957d077e9b3','角煮風 ブロック肉で肉じゃが','MAKE_AHEAD',NULL,'PT10M','PT50M',NULL,0,NULL,'[{"name":"豚バラブロック肉 500g"},{"name":"長ねぎの青い部分 1本分"},{"name":"生姜 20g"},{"name":"水 適量"},{"name":"じゃがいも 5個"},{"name":"玉ねぎ 2個"},{"name":"にんじん 1本"},{"name":"しょうゆ 大さじ2.5"},{"name":"みりん 大さじ2.5"}]','[{"text":"じゃがいもは芽を取り除き、皮をむいておきます。にんじんは皮をむいておきます。"},{"text":"生姜は皮付きのまま薄切りにします。"},{"text":"じゃがいもは半分に切ります。にんじんはヘタを切り落とし、乱切りにします。玉ねぎは8等分のくし切りにします。"},{"text":"鍋に豚バラブロック肉と1、長ねぎの青い部分を入れ、被るくらいの水を注いで強火で加熱します。"},{"text":"ひと煮立ちしたら中火で30分ゆでます。ゆで汁を300ml残してお湯を切り、豚バラブロック肉は粗熱を取って3cm幅に切ります。"},{"text":"鍋に2と4、(A)を入れて中火で煮ます。ひと煮立ちしたら落し蓋をして、さらに20分ほど煮ます。"},{"text":"味がよく染みたら火から下ろして器に盛り付け、絹さやを添えて完成です。"}]','https://kurashiru.com/recipes/c5fe2a37-9c45-4e20-ab29-696fea26de2e',NULL,'{"name":"角煮風 ブロック肉で肉じゃが","cookingMode":"DINNER","prepTime":"PT10M","cookTime":"PT50M","recipeYield":{"value":2,"unit":"食分"},"url":"https://kurashiru.com/recipes/c5fe2a37-9c45-4e20-ab29-696fea26de2e","recipeIngredient":[{"name":"豚バラブロック肉 500g"},{"name":"長ねぎの青い部分 1本分"},{"name":"生姜 20g"},{"name":"水 適量"},{"name":"じゃがいも 5個"},{"name":"玉ねぎ 2個"},{"name":"にんじん 1本"},{"name":"しょうゆ 大さじ2.5"},{"name":"みりん 大さじ2.5"}],"recipeInstructions":[{"text":"じゃがいもは芽を取り除き、皮をむいておきます。にんじんは皮をむいておきます。"},{"text":"生姜は皮付きのまま薄切りにします。"},{"text":"じゃがいもは半分に切ります。にんじんはヘタを切り落とし、乱切りにします。玉ねぎは8等分のくし切りにします。"},{"text":"鍋に豚バラブロック肉と1、長ねぎの青い部分を入れ、被るくらいの水を注いで強火で加熱します。"},{"text":"ひと煮立ちしたら中火で30分ゆでます。ゆで汁を300ml残してお湯を切り、豚バラブロック肉は粗熱を取って3cm幅に切ります。"},{"text":"鍋に2と4、(A)を入れて中火で煮ます。ひと煮立ちしたら落し蓋をして、さらに20分ほど煮ます。"},{"text":"味がよく染みたら火から下ろして器に盛り付け、絹さやを添えて完成です。"}],"notes":"味付け濃かったら調味料減らすか煮汁増やす"}','味付け濃かったら調味料減らすか煮汁増やす',1782539879,1782539962);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('5afad4a0-8e39-4b84-b930-9648cc7401f3','ベーコン&ソーセージじゃがいものハーブスープ','["MAKE_AHEAD"]',NULL,'PT15M','PT20M',NULL,0,NULL,'[{"name":"厚切りベーコン (1cm幅に切る) 150g"},{"name":"ベース野菜MIX 400gくらい"},{"name":"じゃがいも (角切り) 3個"},{"name":"白細ソーセージ"},{"name":"フランクフルター"},{"name":"水 500mlくらい？？"},{"name":"塩 10g（鶏がらスープも入れる）"},{"name":"ブラックペッパーパウダー 1.0g"},{"name":"ローレル 4枚"},{"name":"タイム 2g"},{"name":"ディル 2g"},{"name":"マジョラム 少々"}]','[{"text":"鍋にオリーブオイルを熱し、にんにく、ベーコン、ベース野菜MIXを炒める。（ベーコンの表面の色が変わり、玉ねぎが透明になるくらいまで炒める。）"},{"text":"野菜にだいたい火が通ったら、ソーセージ以外の残りの材料とスパイスとハーブを全て加える。沸騰したら蓋をして10分ほど煮込む。"},{"text":"じゃがいもが柔らかくなったら、ソーセージを加え、さっと温めるくらいに煮込む。お好みでディル(分量外)を飾る。"}]',NULL,'["uploads/99c41632-719d-40a5-91e6-0e63b7028ba7-1000004561.jpg"]','{"name":"ベーコン&ソーセージじゃがいものハーブスープ","cookingMode":"DINNER","prepTime":"PT15M","cookTime":"PT20M","recipeYield":{"value":3,"unit":"食分"},"images":["uploads/99c41632-719d-40a5-91e6-0e63b7028ba7-1000004561.jpg"],"recipeIngredient":[{"name":"厚切りベーコン (1cm幅に切る) 150g"},{"name":"ベース野菜MIX 400gくらい"},{"name":"じゃがいも (角切り) 3個"},{"name":"白細ソーセージ"},{"name":"フランクフルター"},{"name":"水 500mlくらい？？"},{"name":"塩 10g（鶏がらスープも入れる）"},{"name":"ブラックペッパーパウダー 1.0g"},{"name":"ローレル 4枚"},{"name":"タイム 2g"},{"name":"ディル 2g"},{"name":"マジョラム 少々"}],"recipeInstructions":[{"text":"鍋にオリーブオイルを熱し、にんにく、ベーコン、ベース野菜MIXを炒める。（ベーコンの表面の色が変わり、玉ねぎが透明になるくらいまで炒める。）"},{"text":"野菜にだいたい火が通ったら、ソーセージ以外の残りの材料とスパイスとハーブを全て加える。沸騰したら蓋をして10分ほど煮込む。"},{"text":"じゃがいもが柔らかくなったら、ソーセージを加え、さっと温めるくらいに煮込む。お好みでディル(分量外)を飾る。"}],"notes":""}','',1782543667,1783752852);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('a4a6c883-b016-4613-a124-577823642ce6','枝豆のゆで方','DINNER',NULL,'PT1M','PT4M',NULL,0,NULL,'[{"name":"枝豆 200g"},{"name":"水 200g"},{"name":"塩 6g"}]','[{"text":"鍋に材料をすべて入れて混ぜ、強火にかける。"},{"text":"沸騰したらふたをして中火で3～4分、少し硬めにゆでる。"},{"text":"火を止めてそのまま粗熱を取る。途中何度か上下を返し、枝豆を塩水に浸しながら冷ます。"}]',NULL,'["uploads/ead413d7-1304-4f63-a68c-76d1d93ee807-1000007249.jpg"]','{"name":"結局一番おいしい枝豆のゆで方","cookingMode":"DINNER","tags":["稲田俊輔"],"prepTime":"PT1M","cookTime":"PT4M","images":["uploads/ead413d7-1304-4f63-a68c-76d1d93ee807-1000007249.jpg"],"recipeIngredient":[{"name":"枝豆 200g"},{"name":"水 200g"},{"name":"塩 6g"}],"recipeInstructions":[{"text":"鍋に材料をすべて入れて混ぜ、強火にかける。"},{"text":"沸騰したらふたをして中火で3～4分、少し硬めにゆでる。"},{"text":"火を止めてそのまま粗熱を取る。途中何度か上下を返し、枝豆を塩水に浸しながら冷ます。"}],"notes":""}','',1782544462,1783828420);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('70ab8d37-b45d-4f46-8126-2f6c22bbddd3','グラタンドフィノワーズ','DINNER',NULL,'PT15M','PT30M',NULL,0,NULL,'[{"name":"じゃがいも (スライス) 200g"},{"name":"にんにく (スライス) 5g"},{"name":"牛乳 150g"},{"name":"塩 1.2g"},{"name":"ローレル 1枚"},{"name":"こしょう 少々"},{"name":"ナツメグ (あれば) 少々"},{"name":"シュレッドチーズ 適量 (30～100g)"}]','[{"text":"鍋にチーズ以外の材料を入れてふきこぼれないように中～弱火にかけ、じゃがいもに火が通って、牛乳にとろみがついたら火からおろす。"},{"text":"耐熱皿に1を移し、シュレッドチーズをのせ、トースターなどでチーズに焼き目が付くまで焼く。"}]',NULL,'["uploads/b63d03c1-5661-42ec-8b96-7c999c3cddbc-1000007250.jpg"]','{"name":"グラタンドフィノワーズ","cookingMode":"DINNER","prepTime":"PT15M","cookTime":"PT30M","images":["uploads/b63d03c1-5661-42ec-8b96-7c999c3cddbc-1000007250.jpg"],"recipeIngredient":[{"name":"じゃがいも (スライス) 200g"},{"name":"にんにく (スライス) 5g"},{"name":"牛乳 150g"},{"name":"塩 2g"},{"name":"ローレル 1枚"},{"name":"こしょう 少々"},{"name":"ナツメグ (あれば) 少々"},{"name":"シュレッドチーズ 適量 (30～100g)"}],"recipeInstructions":[{"text":"鍋にチーズ以外の材料を入れてふきこぼれないように中～弱火にかけ、じゃがいもに火が通って、牛乳にとろみがついたら火からおろす。"},{"text":"耐熱皿に1を移し、シュレッドチーズをのせ、トースターなどでチーズに焼き目が付くまで焼く。"}],"notes":""}',replace('チーズ70gで作った\n塩はオリジナルは2gだったが、1.2gに減らした','\n',char(10)),1782544578,1782599196);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('b7430426-f3b0-4287-b2a0-49558511f124','ほうれん草のオイスターバター','DINNER',NULL,'PT10M','PT5M',NULL,0,NULL,'[{"name":"ほうれん草 100g"},{"name":"バター 10g"},{"name":"オイスターソース 10g"}]','[{"text":"鍋に湯を沸かし、ほうれん草をさっとゆでる。水にさらして水けを絞り、食べやすい長さに切る。"},{"text":"フライパンにバターを溶かし、①を入れ、バターを含ませるように中火で炒める。"},{"text":"バターが全体に行き渡ったら、オイスターソースを加えてさっと炒め合わせる。"}]',NULL,'["uploads/e32f0235-147e-4db4-b633-e4dcda19ede9-1000007251.jpg"]','{"name":"ほうれん草のオイスターバター","cookingMode":"DINNER","prepTime":"PT10M","cookTime":"PT5M","images":["uploads/e32f0235-147e-4db4-b633-e4dcda19ede9-1000007251.jpg"],"recipeIngredient":[{"name":"ほうれん草 100g"},{"name":"バター 10g"},{"name":"オイスターソース 10g"}],"recipeInstructions":[{"text":"鍋に湯を沸かし、ほうれん草をさっとゆでる。水にさらして水けを絞り、食べやすい長さに切る。"},{"text":"フライパンにバターを溶かし、①を入れ、バターを含ませるように中火で炒める。"},{"text":"バターが全体に行き渡ったら、オイスターソースを加えてさっと炒め合わせる。"}],"notes":""}','',1782546673,1782601093);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('de1b52f4-d416-4aa2-97b5-336f1a0d8377','じゃがいもと醤油バター煮','DINNER',NULL,'PT10M','PT25M','{"name":"Infant"}',0,NULL,'[{"name":"じゃがいも（大きめのひと口大に切る） 200g"},{"name":"濃口醤油 10g"},{"name":"バター 20g"},{"name":"水 100g"}]','[{"text":"鍋にすべての材料を入れ、ふたをして中～弱火で煮る。"},{"text":"じゃがいもに火が通ったらふたを取って余分な水分を飛ばすように煮詰める。"}]',NULL,'["uploads/2988c941-10dd-434c-a7f1-fd751b19af26-1000007252.jpg"]','{"name":"じゃがいもと醤油バター煮","cookingMode":"DINNER","prepTime":"PT10M","cookTime":"PT25M","suitableForKids":{"name":"Infant"},"images":["uploads/2988c941-10dd-434c-a7f1-fd751b19af26-1000007252.jpg"],"recipeIngredient":[{"name":"じゃがいも（大きめのひと口大に切る） 200g"},{"name":"濃口醤油 10g"},{"name":"バター 20g"},{"name":"水 100g"}],"recipeInstructions":[{"text":"鍋にすべての材料を入れ、ふたをして中～弱火で煮る。"},{"text":"じゃがいもに火が通ったらふたを取って余分な水分を飛ばすように煮詰める。"}],"notes":""}','',1782546830,1782599449);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('bf8d91a6-4425-4da0-8771-ae57cc75b27e','南京まんじゅう','["LUNCH","DINNER"]',NULL,'PT10M','PT10M',NULL,0,NULL,'[{"name":"かぼちゃ (乱切り) 100g"},{"name":"かたくり粉 10g"},{"name":"塩 1g"},{"name":"サラダ油 適量"},{"name":"バター、濃口醤油 各適量"}]','[{"text":"かぼちゃにごく少量の水(分量外)を加え、電子レンジに2分かけて完全に柔らかくする。"},{"text":"①をしゃもじなどで潰しながら、かたくり粉と塩を加えて満遍なく混ぜる。円盤状に成形する。"},{"text":"フライパンに油をひき、②を中火で両面焼き、こんがりと焼けたらバターと醤油を加えてさっと絡める。※お好みで「追いバター」をのせても。"}]',NULL,'["uploads/534ccd2e-3e25-4647-b44f-0d5868ac5a5c-1000007294.jpg"]','{"name":"南京まんじゅう","cookingMode":["LUNCH","DINNER"],"tags":["稲田俊輔"],"prepTime":"PT10M","cookTime":"PT10M","images":["uploads/534ccd2e-3e25-4647-b44f-0d5868ac5a5c-1000007294.jpg"],"recipeIngredient":[{"name":"かぼちゃ (乱切り) 100g"},{"name":"かたくり粉 10g"},{"name":"塩 1g"},{"name":"サラダ油 適量"},{"name":"バター、濃口醤油 各適量"}],"recipeInstructions":[{"text":"かぼちゃにごく少量の水(分量外)を加え、電子レンジに2分かけて完全に柔らかくする。"},{"text":"①をしゃもじなどで潰しながら、かたくり粉と塩を加えて満遍なく混ぜる。円盤状に成形する。"},{"text":"フライパンに油をひき、②を中火で両面焼き、こんがりと焼けたらバターと醤油を加えてさっと絡める。※お好みで「追いバター」をのせても。"}],"notes":""}',NULL,1783212228,1783212228);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('b87c71f9-efc0-4be4-98ad-e776c0b6cf5b','野菜たっぷりミートソーススパゲッティ','["LUNCH"]',NULL,'PT20M','PT35M','{"name":"Child"}',0,NULL,'[{"name":"にんじん ½本"},{"name":"玉ねぎ 1個"},{"name":"えのき（しめじに変えてもいい） 1袋"},{"name":"ピーマン 2個"},{"name":"豚挽肉（合挽き肉に変えてもいい） 300g"},{"name":"油 大さじ½"},{"name":"A ホールトマト缶 1缶 (400g)"},{"name":"A ケチャップ 大さじ3"},{"name":"A ウスターソース 大さじ2"},{"name":"A 洋風スープの素 (顆粒) 小さじ1"},{"name":"A ローリエ あきら苦手かもだから一旦入れない"},{"name":"塩こしょう 少々"},{"name":"スパゲッティ 260g"}]','[{"text":"にんじん、玉ねぎ、ピーマンを5mmの角切りに、えのきは2mm幅に刻む"},{"text":"フライパンに油をひき、挽肉を炒める。色が変ったら(1)を入れて混ぜてから、蓋をして約10分弱火で蒸す"},{"text":"野菜から水分が出てきたら、Aを入れて木ベラでトマトを荒くつぶしてから混ぜる。蓋を外して中火で水分を飛ばしながら炒める"},{"text":"とろみが出てきたら、塩こしょうで味を整える"},{"text":"ゆで上がったスパゲッティにかける"}]',NULL,'["uploads/f4af69c0-8417-4dd1-bf41-b9df5dd143f5-1000007309.jpg"]','{"name":"野菜たっぷりミートソーススパゲッティ","cookingMode":["MAKE_AHEAD","LUNCH","DINNER"],"prepTime":"PT20M","cookTime":"PT35M","suitableForKids":{"name":"Child"},"images":["uploads/f4af69c0-8417-4dd1-bf41-b9df5dd143f5-1000007309.jpg"],"recipeIngredient":[{"name":"にんじん ½本"},{"name":"玉ねぎ 1個"},{"name":"えのき（しめじに変えてもいい） 1袋"},{"name":"ピーマン 2個"},{"name":"豚挽肉（合挽き肉に変えてもいい"},{"name":"） 300g"},{"name":"油 大さじ½"},{"name":"A ホールトマト缶 1缶 (400g)"},{"name":"A ケチャップ 大さじ3"},{"name":"A ウスターソース 大さじ2"},{"name":"A 洋風スープの素 (顆粒) 小さじ1"},{"name":"A ローリエ 2枚"},{"name":"塩こしょう 少々"},{"name":"スパゲッティ 260g"}],"recipeInstructions":[{"text":"にんじん、玉ねぎ、ピーマンを5mmの角切りに、えのきは2mm幅に刻む"},{"text":"フライパンに油をひき、挽肉を炒める。色が変ったら(1)を入れて混ぜてから、蓋をして約10分弱火で蒸す"},{"text":"野菜から水分が出てきたら、Aを入れて木ベラでトマトを荒くつぶしてから混ぜる。蓋を外して中火で水分を飛ばしながら炒める"},{"text":"とろみが出てきたら、塩こしょうで味を整える"},{"text":"ゆで上がったスパゲッティにかける"}],"notes":""}','合い挽きでやるなら油は要らない',1783218873,1783226150);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('289263fd-d5e5-44bb-bb53-0970a878b74f','マカロニサラダ','["MAKE_AHEAD","LUNCH","DINNER"]',NULL,'PT15M','PT15M','{"name":"Children"}',0,NULL,'[{"name":"マカロニ (乾燥) 100g"},{"name":"きゅうり 1本 (100g)"},{"name":"ハム 3〜4枚 (45〜60g)"},{"name":"ゆで卵 2個"},{"name":"マヨネーズ 大さじ1.5くらい？様子見で"},{"name":"コンソメ (顆粒) 小さじ1/4"},{"name":"砂糖 小さじ1/2"},{"name":"オリーブオイル 小さじ1 (追加調味料)"},{"name":"マヨネーズ 大さじ1/2 (追加調味料)"},{"name":"塩 少々 (追加調味料)"},{"name":"ブラックペッパー 適量 (追加調味料)"}]','[{"text":"きゅうりは薄い輪切りにして塩ひとつまみ(分量外)でもみ、3分ほどおいたら水ですすぎ、ぎゅっとしぼって水気を切る。"},{"text":"ハムは2〜3cm長さの細切りにする。"},{"text":"ゆで卵は1.5cmの角切りにする。"},{"text":"マカロニは、湯(分量外)で袋の表示時間通りにゆで、水気を切ってオリーブオイルを絡ませる。"},{"text":"ボウルにきゅうり、ハム、ゆで卵、ゆでたマカロニ、マヨネーズ大さじ1、牛乳大さじ1、顆粒コンソメ小さじ1/4、砂糖小さじ1/2を入れて和える。"},{"text":"子ども用として50gほど(大人2食分をとりわけ)を取り分け、残りの大人用2食分には追加調味料（マヨネーズ大さじ1/2、塩少々、ブラックペッパー適量）を入れて和える。"}]',NULL,'["uploads/ee2f6779-c529-41a9-bce1-6ed61f3687af-1000004729.png"]','{"name":"マカロニサラダ","cookingMode":["MAKE_AHEAD","LUNCH","DINNER"],"prepTime":"PT15M","cookTime":"PT15M","suitableForKids":{"name":"Children"},"recipeYield":{"value":2,"unit":"L"},"images":["uploads/ee2f6779-c529-41a9-bce1-6ed61f3687af-1000004729.png"],"recipeIngredient":[{"name":"マカロニ (乾燥) 100g"},{"name":"きゅうり 1本 (100g)"},{"name":"ハム 3〜4枚 (45〜60g)"},{"name":"ゆで卵 2個"},{"name":"マヨネーズ 大さじ1.5くらい？様子見で"},{"name":"コンソメ (顆粒) 小さじ1/4"},{"name":"砂糖 小さじ1/2"},{"name":"オリーブオイル 小さじ1 (追加調味料)"},{"name":"マヨネーズ 大さじ1/2 (追加調味料)"},{"name":"塩 少々 (追加調味料)"},{"name":"ブラックペッパー 適量 (追加調味料)"}],"recipeInstructions":[{"text":"きゅうりは薄い輪切りにして塩ひとつまみ(分量外)でもみ、3分ほどおいたら水ですすぎ、ぎゅっとしぼって水気を切る。"},{"text":"ハムは2〜3cm長さの細切りにする。"},{"text":"ゆで卵は1.5cmの角切りにする。"},{"text":"マカロニは、湯(分量外)で袋の表示時間通りにゆで、水気を切ってオリーブオイルを絡ませる。"},{"text":"ボウルにきゅうり、ハム、ゆで卵、ゆでたマカロニ、マヨネーズ大さじ1、牛乳大さじ1、顆粒コンソメ小さじ1/4、砂糖小さじ1/2を入れて和える。"},{"text":"子ども用として50gほど(大人2食分をとりわけ)を取り分け、残りの大人用2食分には追加調味料（マヨネーズ大さじ1/2、塩少々、ブラックペッパー適量）を入れて和える。"}],"notes":""}',NULL,1783746733,1783746733);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('7d4c9f13-8373-4c6a-831a-73d85aab2b5c','基本の豚汁','["MAKE_AHEAD","LUNCH","DINNER"]',NULL,'PT20M','PT20M','{"name":"Children"}',0,NULL,'[{"name":"豚バラ肉薄切り 150～200ｇ"},{"name":"大根 1/2本"},{"name":"にんじん 1本"},{"name":"ごぼう 1本"},{"name":"玉ねぎ 1玉"},{"name":"里芋 4個（約150ｇ）"},{"name":"長ねぎ（白ねぎ） 1本"},{"name":"水またはだし汁 1リットル"},{"name":"味噌 大さじ5～6ほど"},{"name":"一味唐辛子 好みで少々"},{"name":"サラダ油やごま油 小さじ1～2"}]','[{"text":"大根、にんじんを半月切りやいちょう切り（厚さ5mm程度）に、長ねぎを1cm幅の斜め切りに、玉ねぎを5mm幅に切る。ごぼうは小さめの乱切りにして水にさらし、里芋は大きめのひと口大に切る。豚バラ肉は2～3cm幅に、いんげんはヘタを落として斜め切りにする。"},{"text":"鍋にサラダ油またはごま油小さじ1～2を入れて中火にかけ、いんげん以外の野菜（大根、にんじん、ごぼう、玉ねぎ、里芋、長ねぎ）をすべて加えて1～2分炒める。"},{"text":"一度火を止め、箸で豚肉をほぐしながら野菜の上に広げ入れる。"},{"text":"弱めの中火にかけ、全体を混ぜながら2～3分かけてじっくり炒める。"},{"text":"水またはだし汁1リットルを鍋に加え、火を強めて沸騰を待つ。沸騰したら出てくるアクをお玉で軽くすくい取る。"},{"text":"味噌の半量（大さじ3）を溶き入れ、弱火で7～8分ほどコトコトと煮て具材に火を通す。"},{"text":"大きめの里芋に竹串を刺して火通りを確認し、火が通っていたらいんげんを加えてさらに2～3分煮る。"},{"text":"最後に残りの味噌（大さじ2～3）を溶き入れる（合計で大さじ5～6を目安に調整）。"},{"text":"椀に盛り、好みで一味唐辛子などをふりかけていただく。"}]',NULL,NULL,'{"name":"基本の豚汁","cookingMode":["MAKE_AHEAD","LUNCH","DINNER"],"prepTime":"PT20M","cookTime":"PT20M","suitableForKids":{"name":"Children"},"recipeYield":{"value":3,"unit":"L"},"recipeIngredient":[{"name":"豚バラ肉薄切り 150～200ｇ"},{"name":"大根 1/2本"},{"name":"にんじん 1本"},{"name":"ごぼう 1本"},{"name":"玉ねぎ 1玉"},{"name":"里芋 4個（約150ｇ）"},{"name":"長ねぎ（白ねぎ） 1本"},{"name":"水またはだし汁 1リットル"},{"name":"味噌 大さじ5～6ほど"},{"name":"一味唐辛子 好みで少々"},{"name":"サラダ油やごま油 小さじ1～2"}],"recipeInstructions":[{"text":"大根、にんじんを半月切りやいちょう切り（厚さ5mm程度）に、長ねぎを1cm幅の斜め切りに、玉ねぎを5mm幅に切る。ごぼうは小さめの乱切りにして水にさらし、里芋は大きめのひと口大に切る。豚バラ肉は2～3cm幅に、いんげんはヘタを落として斜め切りにする。"},{"text":"鍋にサラダ油またはごま油小さじ1～2を入れて中火にかけ、いんげん以外の野菜（大根、にんじん、ごぼう、玉ねぎ、里芋、長ねぎ）をすべて加えて1～2分炒める。"},{"text":"一度火を止め、箸で豚肉をほぐしながら野菜の上に広げ入れる。"},{"text":"弱めの中火にかけ、全体を混ぜながら2～3分かけてじっくり炒める。"},{"text":"水またはだし汁1リットルを鍋に加え、火を強めて沸騰を待つ。沸騰したら出てくるアクをお玉で軽くすくい取る。"},{"text":"味噌の半量（大さじ3）を溶き入れ、弱火で7～8分ほどコトコトと煮て具材に火を通す。"},{"text":"大きめの里芋に竹串を刺して火通りを確認し、火が通っていたらいんげんを加えてさらに2～3分煮る。"},{"text":"最後に残りの味噌（大さじ2～3）を溶き入れる（合計で大さじ5～6を目安に調整）。"},{"text":"椀に盛り、好みで一味唐辛子などをふりかけていただく。"}],"notes":""}',NULL,1783748109,1783748109);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('db58d87d-ac88-48a6-9de4-69f133a178f6','カリッと豚ごま揚げ','["MAKE_AHEAD","DINNER"]',NULL,'PT45M','PT10M','{"name":"Children"}',0,NULL,'[{"name":"豚こま切れ肉 200g"},{"name":"醤油 大さじ1"},{"name":"はちみつ 大さじ1"},{"name":"にんにく(すりおろし) 小さじ1/2"},{"name":"片栗粉 大さじ2"},{"name":"白ごま 大さじ1"},{"name":"揚げ油 適量"}]','[{"text":"ボウルに豚こま切れ肉と醤油 大さじ1、はちみつ 大さじ1、にんにく(すりおろし) 小さじ1/2を入れ、ざっと揉み込んで約30分寝かせる。"},{"text":"ボウルに片栗粉と白ごまを混ぜておき、1の肉を入れて手でざっとかき混ぜる。"},{"text":"フライパンに高さ1.5mmの油を入れ、中温に熱し、一枚ずつ豚肉を入れる。時々菜箸で返しながら約1分、色よく揚がったらお皿に盛る。"}]',NULL,'["uploads/fec79d74-0a89-4917-95fe-2752865272d4-1000004730.jpg"]','{"name":"カリッと豚ごま揚げ","cookingMode":["MAKE_AHEAD","LUNCH","DINNER"],"prepTime":"PT45M","cookTime":"PT10M","suitableForKids":{"name":"Children"},"images":["uploads/fec79d74-0a89-4917-95fe-2752865272d4-1000004730.jpg"],"recipeIngredient":[{"name":"豚こま切れ肉 200g"},{"name":"醤油 大さじ1"},{"name":"はちみつ 大さじ1"},{"name":"にんにく(すりおろし) 小さじ1/2"},{"name":"片栗粉 大さじ2"},{"name":"白ごま 大さじ1"},{"name":"揚げ油 適量"}],"recipeInstructions":[{"text":"ボウルに豚こま切れ肉と醤油 大さじ1、はちみつ 大さじ1、にんにく(すりおろし) 小さじ1/2を入れ、ざっと揉み込んで約30分寝かせる。"},{"text":"ボウルに片栗粉と白ごまを混ぜておき、1の肉を入れて手でざっとかき混ぜる。"},{"text":"フライパンに高さ1.5mmの油を入れ、中温に熱し、一枚ずつ豚肉を入れる。時々菜箸で返しながら約1分、色よく揚がったらお皿に盛る。"}],"notes":""}','',1783749838,1784336997);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('cd13a256-b607-4a50-97eb-cfeb4a3c1c86','ぶりの竜田揚げ（ぶりから）','["DINNER"]',NULL,'PT18M','PT12M','{"name":"Child"}',0,NULL,'[{"name":"ぶり 4切れ (合計320g)"},{"name":"しょうゆ 大さじ2"},{"name":"酒 大さじ1と1/2"},{"name":"しょうが (チューブ) 4cm"},{"name":"片栗粉 大さじ6"},{"name":"揚げ油 適量"}]','[{"text":"ぶりはキッチンペーパーで水気をふきとり、ひと口サイズに切りわける。"},{"text":"ポリ袋にぶり、しょうゆ、酒、しょうがをそれぞれすべて入れてもみ、冷蔵庫で10分ほど寝かせる。"},{"text":"1の漬け汁を捨て、片栗粉を全体にまぶす。"},{"text":"フライパンに揚げ油を底から0.5cmほど入れ、子ども用40gほど×2食分を入れて両面を揚げ焼きにする。火が通ってこんがりきつね色になったらバットにあげる。目安として片面2分ずつ"}]',NULL,'["uploads/24f4d182-131d-41cf-bd5d-27bebb0f7cda-1000007390.jpg"]','{"name":"ぶりぶりの竜田揚げ","cookingMode":["MAKE_AHEAD","LUNCH","DINNER"],"prepTime":"PT18M","cookTime":"PT12M","suitableForKids":{"name":"Child"},"images":["uploads/24f4d182-131d-41cf-bd5d-27bebb0f7cda-1000007390.jpg"],"recipeIngredient":[{"name":"ぶり 4切れ (合計320g)"},{"name":"しょうゆ 大さじ2"},{"name":"酒 大さじ1と1/2"},{"name":"しょうが (チューブ) 4cm"},{"name":"塩 ふたつまみ"},{"name":"片栗粉 大さじ6"},{"name":"揚げ油 適量"}],"recipeInstructions":[{"text":"ぶりはキッチンペーパーで水気をふきとり、ひと口サイズに切りわける。"},{"text":"2枚のポリ袋に大人用と子ども用のぶり、しょうゆ、酒、しょうが、塩（大人用のみ）をそれぞれすべて入れてもみ、冷蔵庫で10分ほど寝かせる。"},{"text":"1の漬け汁を捨て、片栗粉を子ども用は小さじ2、大人用は大きじ4、それぞれポリ袋に入れ、全体にまぶす。"},{"text":"フライパンに揚げ油を底から0.5cmほど入れ、子ども用40gほど×2食分を入れて両面を揚げ焼きにする。火が通ってこんがりきつね色になったらバットにあげる。"},{"text":"同様に大人用2食分も揚げ焼きにする。"}],"notes":""}','',1783759256,1783828419);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('dd882fbd-50c6-446b-8478-145a043dc92c','コンソメスープ','["LUNCH","DINNER"]',NULL,'PT10M','PT20M','{"name":"Child"}',0,NULL,'[{"name":"キャベツ 適量"},{"name":"ニンジン 適量"},{"name":"玉ねぎ 適量"},{"name":"その他野菜 適量"},{"name":"ウインナー 1袋"},{"name":"顆粒コンソメ 2.5g"},{"name":"ブラックペッパー"},{"name":"水 400 ml"}]','[{"text":"野菜を最初に炒めます。"},{"text":"炒めた野菜に水を入れて煮ます。"},{"text":"ウインナーは煮込みの最後の方に入れます。"}]',NULL,NULL,'{"name":"コンソメスープ","cookingMode":["LUNCH","DINNER"],"prepTime":"PT10M","cookTime":"PT20M","suitableForKids":{"name":"Child"},"recipeIngredient":[{"name":"キャベツ 適量"},{"name":"ニンジン 適量"},{"name":"玉ねぎ 適量"},{"name":"その他野菜 適量"},{"name":"ウインナー 適量"},{"name":"コンソメキューブ 1"},{"name":"水 500 ml"}],"recipeInstructions":[{"text":"野菜を最初に炒めます。"},{"text":"炒めた野菜に水を入れて煮ます。"},{"text":"ウインナーは煮込みの最後の方に入れます。"}],"notes":""}','',1783760235,1783776017);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('ad6f9d85-c049-4327-b9c2-52d60d6bd502','牛丼','["MAKE_AHEAD","LUNCH","DINNER"]',NULL,'PT10M','PT15M','{"name":"Children"}',0,NULL,'[{"name":"牛薄切り肉 300g"},{"name":"玉ねぎ 1〜1.5個"},{"name":"A しょうゆ 大さじ1"},{"name":"A 酒 大さじ2"},{"name":"A みりん 大さじ2"},{"name":"A 砂糖 小さじ2"},{"name":"水 200ml"},{"name":"ごま油 適量"}]','[{"text":"1. 玉ねぎは薄切りに、牛肉は4〜5cm幅に切ります。"},{"text":"2. 密閉保存袋に1で準備した玉ねぎと牛肉、およびAの調味料（しょうゆ大さじ1、酒大さじ2、みりん大さじ2、砂糖小さじ2）を入れてよくもみ、空気を抜いて封を閉じ、冷凍庫に入れます。"},{"text":"3. 食べる際は、解凍後、フライパンにごま油をひき、冷凍保存袋の中身と水を加えて火にかけます。ぐつぐつしてきたら弱めの中火にし、途中アクを取りながら煮込みます。"},{"text":"4. 煮汁が少なくなってきたら、子ども用として50gほどを2食分取り分け、牛肉を食べやすい大きさに切ります。"},{"text":"5. 残りの大人用2食分が入ったフライパンに追加調味料（しょうゆ小さじ2、砂糖小さじ1）を入れ、弱めの中火で2分ほど煮込みます。"},{"text":"6. それぞれにお好みで小切りにした小ねぎをのせて完成です。"}]',NULL,'["uploads/d27b2f4b-117f-4e1d-a1c8-6c6e249cd6fa-1000004788.png"]','{"name":"牛丼","cookingMode":["MAKE_AHEAD","LUNCH","DINNER"],"prepTime":"PT10M","cookTime":"PT15M","suitableForKids":{"name":"Children"},"recipeYield":{"value":2,"unit":"食分"},"images":["uploads/d27b2f4b-117f-4e1d-a1c8-6c6e249cd6fa-1000004788.png"],"recipeIngredient":[{"name":"牛薄切り肉 300g"},{"name":"玉ねぎ 1〜1.5個"},{"name":"A しょうゆ 大さじ1"},{"name":"A 酒 大さじ2"},{"name":"A みりん 大さじ2"},{"name":"A 砂糖 小さじ2"},{"name":"水 200ml"},{"name":"ごま油 適量"}],"recipeInstructions":[{"text":"1. 玉ねぎは薄切りに、牛肉は4〜5cm幅に切ります。"},{"text":"2. 密閉保存袋に1で準備した玉ねぎと牛肉、およびAの調味料（しょうゆ大さじ1、酒大さじ2、みりん大さじ2、砂糖小さじ2）を入れてよくもみ、空気を抜いて封を閉じ、冷凍庫に入れます。"},{"text":"3. 食べる際は、解凍後、フライパンにごま油をひき、冷凍保存袋の中身と水を加えて火にかけます。ぐつぐつしてきたら弱めの中火にし、途中アクを取りながら煮込みます。"},{"text":"4. 煮汁が少なくなってきたら、子ども用として50gほどを2食分取り分け、牛肉を食べやすい大きさに切ります。"},{"text":"5. 残りの大人用2食分が入ったフライパンに追加調味料（しょうゆ小さじ2、砂糖小さじ1）を入れ、弱めの中火で2分ほど煮込みます。"},{"text":"6. それぞれにお好みで小切りにした小ねぎをのせて完成です。"}],"notes":""}',NULL,1784352726,1784352726);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('81609b4b-7aad-4313-8cbe-4c358b1d9acf','ポップコーン','["LUNCH"]',NULL,NULL,'PT10M','{"name":"Children"}',0,NULL,'[{"name":"ポップコーン豆 30g"},{"name":"塩 1.5g"},{"name":"米油 12g"}]','[{"text":"ティファール炒め鍋にポップコーン豆、米油、塩を入れて軽く混ぜ、火力5にかける。"},{"text":"しゅわしゅわしてきたらフタをする。"},{"text":"ポップコーン豆がはじける音がしはじめたら、フライパンをゆする。ポップコーンが弾ける音が減ってきたら、火からおろす。"},{"text":"火から下ろしたあともゆすり続け、完全に弾ける音がなくなったか確認する。"},{"text":"蒸れないように、バットや大きめの皿に広げ入れて完成。"}]',NULL,'["81609b4b-7aad-4313-8cbe-4c358b1d9acf/f8aa5440-0879-4425-9dca-bfb7981a3899-1000007438.png"]','{"name":"シンプルな塩味で！ポップコーンの作り方","cookingMode":["LUNCH","DINNER"],"cookTime":"PT10M","suitableForKids":{"name":"Children"},"recipeIngredient":[{"name":"ポップコーン豆 20g"},{"name":"塩 小さじ1/2杯"},{"name":"オリーブオイル 大さじ1杯"}],"recipeInstructions":[{"text":"ポップコーン豆とオリーブオイルを合わせる。フライパンにポップコーン豆とオリーブオイルを合わせものを入れる。フライパンを中火にかける。"},{"text":"ポップコーン豆が白っぽくなってきたらフタをする。"},{"text":"ポップコーン豆がはじける音がしはじめたら、フライパンをゆする。ポップコーンが弾ける音が減ってきたら、火からおろす。"},{"text":"火から下ろしたあともゆすり続け、完全に弾ける音がなくなったか確認する。"},{"text":"蒸れないように、バットや大きめの皿に広げ入れて完成。"}],"notes":""}','もうちょい油を減らす余地はあるかも',1784352946,1784357413);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('282b540e-dc99-4dd5-88a9-61acf5dce1b7','鮭フライ☆オーロラソース','["DINNER"]',NULL,NULL,'PT10M','{"name":"Children"}',0,NULL,'[{"name":"生鮭 3切れ(200g)"},{"name":"塩こしょう 少々"},{"name":"薄力粉、片栗粉 各大さじ1.5"},{"name":"水 大さじ2"},{"name":"パン粉 適量"},{"name":"マヨネーズ 大さじ2"},{"name":"ケチャップ 大さじ1"},{"name":"砂糖、塩こしょう 少々"}]','[{"text":"生鮭はペーパーで水気を拭き取り、2等分に切って塩こしょうをふる。"},{"text":"合わせたA 薄力粉、片栗粉各大さじ1.5、水大さじ2､パン粉の順で衣付けする。"},{"text":"フライパンに油大さじ3を中火で熱し､②をこんがり揚げ焼きにする。"},{"text":"器に盛り、合わせたB マヨネーズ大さじ2、ケチャップ大さじ1、砂糖、塩こしょう少々をかける。"}]','https://oceans-nadia.com/user/484627/recipe/462885',NULL,'{"name":"【鮭フライ☆オーロラソース】子どもも喜ぶお魚レシピ♡","cookingMode":["LUNCH","DINNER"],"cookTime":"PT10M","suitableForKids":{"name":"Children"},"url":"https://oceans-nadia.com/user/484627/recipe/462885","recipeIngredient":[{"name":"生鮭 3切れ(200g)"},{"name":"塩こしょう 少々"},{"name":"薄力粉、片栗粉 各大さじ1.5"},{"name":"水 大さじ2"},{"name":"パン粉 適量"},{"name":"マヨネーズ 大さじ2"},{"name":"ケチャップ 大さじ1"},{"name":"砂糖、塩こしょう 少々"}],"recipeInstructions":[{"text":"生鮭はペーパーで水気を拭き取り、2等分に切って塩こしょうをふる。"},{"text":"合わせたA 薄力粉、片栗粉各大さじ1.5、水大さじ2､パン粉の順で衣付けする。"},{"text":"フライパンに油大さじ3を中火で熱し､②をこんがり揚げ焼きにする。"},{"text":"器に盛り、合わせたB マヨネーズ大さじ2、ケチャップ大さじ1、砂糖、塩こしょう少々をかける。"}],"notes":""}','サーモンフライ',1784364342,1784365640);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('669232a8-4140-4aeb-9f9b-bc794424ad16','夏にぴったり！トマトツナそうめん','["LUNCH","DINNER"]',NULL,'PT0M','PT10M',NULL,0,NULL,'[{"name":"そうめん 200g"},{"name":"お湯 (ゆで用) 適量"},{"name":"氷水 (冷やす用) 適量"},{"name":"トマト 1個"},{"name":"ツナ油漬け (1缶・正味量) 50g"},{"name":"めんつゆ (そうみ) 大さじ1"},{"name":"ごま油 大さじ1"},{"name":"白すりごま 大さじ1"},{"name":"黒こしょう すこし"},{"name":"塩 1.0g"},{"name":"大葉 3枚"}]','[{"text":"大葉は軸を切り落としておきます。トマトはヘタを切り落としておきます。"},{"text":"大葉は千切りにします。"},{"text":"トマトは1cm角に切ります。"},{"text":"ボウルに2、ツナ油漬け、(A)を入れて混ぜ合わせます。"},{"text":"鍋にお湯を沸かし、沸騰したらそうめんを入れてパッケージの表記通りに茹で、お湯を切ります。流水で洗って氷水で冷やし、水気を切ります。"},{"text":"器に4を盛り付け、3をかけ、1をのせて完成です。"}]','https://www.kurashiru.com/recipes/3a2cbf2e-290d-4778-b686-8cc171af3efb',NULL,'{"name":"夏にぴったり！トマトツナそうめん","cookingMode":["LUNCH","DINNER"],"prepTime":"PT0M","cookTime":"PT10M","url":"https://www.kurashiru.com/recipes/3a2cbf2e-290d-4778-b686-8cc171af3efb","recipeIngredient":[{"name":"そうめん 200g"},{"name":"お湯 (ゆで用) 適量"},{"name":"氷水 (冷やす用) 適量"},{"name":"トマト 1個"},{"name":"ツナ油漬け (1缶・正味量) 50g"},{"name":"めんつゆ (2倍濃縮) 大さじ2"},{"name":"ごま油 大さじ1"},{"name":"白すりごま 大さじ1"},{"name":"黒こしょう 小さじ1"},{"name":"塩 小さじ1/2"},{"name":"大葉 3枚"}],"recipeInstructions":[{"text":"大葉は軸を切り落としておきます。トマトはヘタを切り落としておきます。"},{"text":"大葉は千切りにします。"},{"text":"トマトは1cm角に切ります。"},{"text":"ボウルに2、ツナ油漬け、(A)を入れて混ぜ合わせます。"},{"text":"鍋にお湯を沸かし、沸騰したらそうめんを入れてパッケージの表記通りに茹で、お湯を切ります。流水で洗って氷水で冷やし、水気を切ります。"},{"text":"器に4を盛り付け、3をかけ、1をのせて完成です。"}],"notes":""}','ママから不評',1784535338,1784865055);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('717f3118-c54c-4005-999e-830fbb77816e','トマトのハニーマリネ（米酢・米油仕立て）','["LUNCH","DINNER","MAKE_AHEAD"]',NULL,'PT10M','PT15S',NULL,0,NULL,'[{"name":"トマト（中サイズ）: 3個"},{"name":"米酢: 大さじ2"},{"name":"蜂蜜: 大さじ1.5"},{"name":"米油:8g"},{"name":"塩: 0.8g"}]','[{"text":"ボウルに米酢、蜂蜜、塩（1.5g）を入れ、塩と蜂蜜が完全に溶解するまでよく混ぜる。最後に米油を加え、軽く混ぜ合わせて乳化させる（白っぽくとろみが出れば完了）。"},{"text":"トマトのお尻（ヘタの反対側）に浅く十字の切り込みを入れる。沸騰したお湯に10〜15秒ほどくぐらせ、皮がめくれてきたら素早く氷水（または冷水）に取る。急激な温度変化による熱収縮で皮を分離させる。"},{"text":"冷えたトマトの皮を剥き、一口大や、くし切りなど食べやすい大きさにカットする。"},{"text":"1で作成した調味液のボウルにカットしたトマトを投入し、全体に液が均一に絡むように混ぜ合わせる。"},{"text":"ボウルにラップをして、冷蔵庫で30分以上静置する（浸透圧によりトマトから適度な水分が引き出され、味が馴染む）。"}]',NULL,'["717f3118-c54c-4005-999e-830fbb77816e/5eb45ff4-7d65-4e9b-8f89-94f373de011e-1000007580.png"]','{"name":"トマトのハニーマリネ（米酢・米油仕立て）","cookingMode":["LUNCH","DINNER","MAKE_AHEAD"],"prepTime":"PT10M","cookTime":"PT15S","recipeYield":{"value":4,"unit":"食分"},"recipeIngredient":[{"name":"トマト（中サイズ）: 3個"},{"name":"米酢: 大さじ2"},{"name":"蜂蜜: 大さじ1.5"},{"name":"米油: 大さじ1"},{"name":"塩: 0.8g"}],"recipeInstructions":[{"text":"ボウルに米酢、蜂蜜、塩（1.5g）を入れ、塩と蜂蜜が完全に溶解するまでよく混ぜる。最後に米油を加え、軽く混ぜ合わせて乳化させる（白っぽくとろみが出れば完了）。"},{"text":"トマトのお尻（ヘタの反対側）に浅く十字の切り込みを入れる。沸騰したお湯に10〜15秒ほどくぐらせ、皮がめくれてきたら素早く氷水（または冷水）に取る。急激な温度変化による熱収縮で皮を分離させる。"},{"text":"冷えたトマトの皮を剥き、一口大や、くし切りなど食べやすい大きさにカットする。"},{"text":"1で作成した調味液のボウルにカットしたトマトを投入し、全体に液が均一に絡むように混ぜ合わせる。"},{"text":"ボウルにラップをして、冷蔵庫で30分以上静置する（浸透圧によりトマトから適度な水分が引き出され、味が馴染む）。"}],"notes":""}','',1785036718,1785063328);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('f73a4949-7ff5-49e8-a0df-3bd9e50cd975','鶏ガラとごま油で絶品！レンジで作る超簡単もやしナムル','["MAKE_AHEAD","LUNCH","DINNER"]',NULL,'PT0M','PT300S',NULL,0,NULL,'[{"name":"もやし 1袋(200g)"},{"name":"白いりごま 小さじ1"},{"name":"しょうゆ 大さじ1/2"},{"name":"ごま油 小さじ1"},{"name":"鶏ガラスープの素 小さじ1/2"}]','[{"text":"ボウルに☆を入れて混ぜる。"},{"text":"耐熱容器にもやしを入れてふんわりとラップをし、600Wのレンジで2分加熱して水にさらし、水気を切る。"},{"text":"1のボウルにもやしを加え、混ぜる。"}]','https://delishkitchen.tv/recipes/546332612495410305',NULL,'{"name":"鶏ガラとごま油で絶品！レンジで作る超簡単もやしナムル","cookingMode":["MAKE_AHEAD","LUNCH","DINNER"],"prepTime":"PT0M","cookTime":"PT300S","url":"https://delishkitchen.tv/recipes/546332612495410305","recipeIngredient":[{"name":"もやし 1袋(200g)"},{"name":"白いりごま 小さじ1"},{"name":"しょうゆ 大さじ1/2"},{"name":"ごま油 小さじ1"},{"name":"鶏ガラスープの素 小さじ1/2"}],"recipeInstructions":[{"text":"ボウルに☆を入れて混ぜる。"},{"text":"耐熱容器にもやしを入れてふんわりとラップをし、600Wのレンジで2分加熱して水にさらし、水気を切る。"},{"text":"1のボウルにもやしを加え、混ぜる。"}],"notes":""}',NULL,1785122542,1785122542);
INSERT INTO "recipes" ("id","name","cooking_mode","recipe_category","prep_time","cook_time","suitable_for_kids","pinned","recipe_yield","recipe_ingredient","recipe_instructions","url","images","structured_data","notes","created_at","updated_at") VALUES('9af3f2f0-1c04-405b-9e62-de3f3a2771a5','自家製イオン飲料 (スポーツドリンク)','["LUNCH"]',NULL,'PT5M','PT0M',NULL,0,NULL,'[{"name":"水 1L"},{"name":"塩 2g"},{"name":"砂糖 25g"},{"name":"きび砂糖 25g"},{"name":"クエン酸 1.5g（レモン汁などに適宜置き換え）"}]','[{"text":"水1Lに塩2g、砂糖25g、きび砂糖25g、クエン酸1.5gをすべて加えます。"},{"text":"材料が完全に溶けるまでよく混ぜます。"},{"text":"冷蔵庫で冷やしてお召し上がりください。"}]',NULL,NULL,'{"name":"自家製イオン飲料 (スポーツドリンク)","cookingMode":["LUNCH"],"prepTime":"PT5M","cookTime":"PT0M","recipeIngredient":[{"name":"水 1L"},{"name":"塩 2g"},{"name":"砂糖 25g"},{"name":"きび砂糖 25g"},{"name":"クエン酸 1.5g（レモン汁などに適宜置き換え）"}],"recipeInstructions":[{"text":"水1Lに塩2g、砂糖25g、きび砂糖25g、クエン酸1.5gをすべて加えます。"},{"text":"材料が完全に溶けるまでよく混ぜます。"},{"text":"冷蔵庫で冷やしてお召し上がりください。"}],"notes":""}',NULL,1785500835,1785500835);
